-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(4974, { "classic", "forever" }, { deDE = { progress = "<Thrall grunzt.>", completion = "Ihr habt der Streitmacht von Blackrock einen schweren Schlag versetzt, {name}. Da ihr Kriegshäuptling jetzt tot ist, wird die Blackrocklegion erneut im Sumpf des Chaos versinken.\n\nZu Ehren Euer Heldentaten wird Euch das Volk von Kalimdor belohnen!" }, enUS = { progress = "<Thrall grunts.>", completion = "You have dealt a crippling blow to the forces of Blackrock, {name}. With their Warchief slain, the Blackrock legion is once again thrown into the maw of chaos.\n\nIn honor of your heroics, the people of Kalimdor shall be rewarded!" } })
apply(4975, { "classic", "forever" }, { deDE = { completion = "Es ist vollbracht, {name}. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr eine Höllenbestie besiegt habt, war eine große Leistung, und diese Belohnung wird Euch gut zupass kommen. Ich wünsche Euch weiterhin viel Erfolg, {name}." }, enUS = { completion = "It is done, {name}. Simply tell me which you'd prefer: a staff that would require you to use both hands, or an orb so you may use a dagger or sword as your weapon.\n\nTackling the infernal was a great feat on your part and this reward will fit you nicely. I wish you further success in the arts, {name}." } })
apply(4976, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Suche nach Tabetha und der Kugel, {name}?\n\nTabetha hat sich als mehr als hilfreich erwiesen, wenn es um arkane Dinge geht. Sie wird Euch bestimmt gern helfen, falls es Euch gelingt, sie zu finden.", completion = "Gut gemacht, {name}. Das dürfte reichen.\n\nJetzt müsst Ihr nur noch entscheiden, welchen Dämon ich in der gesäuberten Kugel einkerkern soll. Entscheidet Euch, dann habt Ihr einen wunderbaren neuen Gegenstand, den Ihr benutzen könnt." }, enUS = { progress = "How goes your search for Tabetha and the orb, {name}?\n\nTabetha has been more than useful when it comes to matters of the arcane. I'm sure she would have no problem aiding you if you're able to find her.", completion = "Well done, {name}. This will do nicely.\n\nThe only thing left for you to do is to decide on which demon you want me to imprison within the cleansed orb. Do that, and you will have a magnificent new item to wield." } })
apply(4981, { "classic", "forever" }, { deDE = { completion = "Ich kann Euch nicht belügen, {race}. Ich brauchte das Geld! Kibler bezahlt mich sehr, sehr gut - viel besser als es das KEK je könnte.\n\nAber bitte zweifelt nicht an meiner Loyalität! Warum, glaubt Ihr, bin ich wohl hier? Um diesem verrückten Goblin ein paar Eier von exotischen Tieren oder ähnlichen Unfug zu bringen? Nein, nur jemand, der wirklich absolut dämlich ist, würde zur Blackrockspitze kommen, um nach Tieren zu suchen. Tja, ich glaube nicht, dass es allzu viele Leute dieser Art auf der Welt gibt.\n\n\n\nDas würde uns gerade noch fehlen, dass sich solche Leute noch vermehren." }, enUS = { completion = "I won't lie to you, {race}. I needed the money! Kibler pays very, very well - much better than the K.E.F. ever could.\n\nBut don't doubt my loyalties! Why do you think I'm down here? To get that crazy goblin some exotic animal eggs or something equally inane? No, only someone truly daft would come to Blackrock Spire to collect pets. Yep, I don't reckon too many people like that exist in this world.\n\n\n\nThe last thing we need are those kinds of people breeding." } })
apply(4982, { "classic", "forever" }, { deDE = { progress = "Glück gehabt?", completion = "Ihr habt es geschafft! Sobald Lexlort diese Pläne hat, wird er all die üblen Dinge vergessen, die er mir antun wollte.\n\n{name}, Ihr seid mein Held!" }, enUS = { progress = "Any luck?", completion = "You've done it! Once Lexlort has these plans, he'll forget all about the nasty things he wanted to do to me.\n\n{name}, you're my hero!" } })
apply(4983, { "classic", "forever" }, { deDE = { progress = "Wo ist der Goblin???", completion = "Eines muss man ihr lassen, sie hat es wieder einmal geschafft, sich aus einer heiklen Situation herauszulavieren! Diese Berichte werden sich als unschätzbar erweisen, wenn wir es wieder mit den Orcs des Blackrockklans zu tun bekommen.\n\nNatürlich werdet Ihr für Eure harte Arbeit belohnt werden." }, enUS = { progress = "Where's the goblin???", completion = "I've got to hand it to her; she's managed to weasel her way out of another sticky situation! These reports will prove to be invaluable in our dealings with the Blackrock orcs.\n\nOf course, you will be rewarded for your hard work." } })
apply(4984, { "classic", "forever" }, { deDE = { progress = "Die von der Seuche infizierten Wölfe müssen getötet werden, {name}. Die Krankheit, an der sie leiden, ist unheilbar. Ich habe es versucht... Ich habe es versucht, bis ich mich selbst mit dieser Seuche angesteckt habe.", completion = "Ich... Ich spüre, dass die Seelen der Wölfe, die Ihr getötet habt, jetzt endlich Ruhe finden. Sie - und ich - danken Euch für die gnädige Befreiung.\n\nDie Wölfe sind jedoch nicht die Einzigen, die an diesem verfluchten Ort leiden, {name}. Bitte, ich benötige noch einmal Eure Hilfe." }, enUS = { progress = "The wolves that are infected with the plague must be put down, {name}.  The disease they carry cannot be cured.  I tried... I tried until I succumbed to the plague myself.", completion = "I... I sense that the souls of those wolves you have put down now have rest.  They - and I - thank you for a merciful release.\n\nThe wolves are not alone in their suffering within this damnable place, {name}.  Please, I have need of you once more." } })
apply(4985, { "classic", "forever" }, { deDE = { progress = "Ich höre Eure Schritte, {name}. Meine Sehkraft ist geschwunden, aber ich kann immer noch Dinge in meiner Umgebung spüren. Habt Ihr die kranken Grizzlys von ihrem Elend erlöst?", completion = "Ich weiß, dass die Grizzlys tot sind und ihre Qual ein Ende hat. Ich... Ich habe da noch etwas für Euch. Ich habe es auf diesem... diesem Ast niedergeschrieben, weil ich fühle, dass meine Zeit in diesem Reich zu Ende geht.\n\nJa... Ich habe das Ende erreicht. Habt nochmals Dank... die Kreaturen dieses verfluchten Landes können in Frieden ruhen... und das werde ich jetzt auch.\n\nDer Druide seufzt noch einmal tief auf, dann folgt ein rasselndes Geräusch des Todes. Sein Körper liegt reglos auf dem Boden der Hütte." }, enUS = { progress = "I hear your footsteps, {name}.  My vision has faded from me, but I still am able to sense things around me.  Have you ended the misery of the disease-ridden grizzlies?", completion = "\"I know that the grizzles have been put down, their torment at an end.  I... I have one more thing for you.  I wrote it down on... on this branch, sensing that my time in this realm had come to an end.\n\nIndeed... I am at that end.  Thank you again friend... the creatures of this accursed land may rest... and now shall I.\"\n\nWith that, a heavy sigh is uttered by the druid, followed by what sounds like a death rattle.  His body lies motionless on the cottage floor." } })
apply(4986, { "classic", "forever" }, { deDE = { progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, {class}. Was können wir für Euch tun?", completion = "Das... ist ziemlich seltsam. Dieser Druide - ein Taurendruide noch dazu - hat Euch eine Menge wertvoller Informationen bezüglich des Ausmaßes der Seuche der Geißel anvertraut. Es überrascht mich, dass ein Tauren einem wie Euch, {race}, Informationen überlassen würde, noch dazu freiwillig, wenn es stimmt, was Ihr sagt. Wir können sie aber wirklich gut gebrauchen. Vielleicht sind die Tauren ja doch nicht so weit von Cenarius abgefallen, wie Fandral meint...\n\nÄhm, wie dem auch sei, bitte nehmt dies als Zeichen des Danks des Zirkels des Cenarius." }, enUS = { progress = "On behalf of the Cenarion Circle, I bid you welcome to this enclave, {class}.  What business do you have with us?", completion = "This... this is quite strange.  This druid - this tauren druid no less - entrusted you with a great deal of valuable information on the extent of the Scourge's plague.  I am surprised a tauren would give a {race} such information, and freely at that if what you say is true.  We will make good use of this, I promise you.  Perhaps the tauren have not fallen as far from Cenarius as Fandral would believe...\n\nErm, anyway, please - accept this as a token of thanks from the Cenarion Circle." } })
apply(4987, { "classic", "forever" }, { deDE = { progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, {class}. Was können wir für Euch tun?", completion = "Das ist von Mulgris, sagt Ihr? Wir haben gehört, dass er danach trachtete, den leidenden Kreaturen der Pestländer zu helfen, aber das ist jetzt doch etwas unerwartet... und ziemlich traurig. Mulgris ist... war ein guter Freund. Ich werde sehr um ihn trauern.\n\nSeine Bemühungen waren Dank Eures Eifers jedoch nicht umsonst. Auf diesem Ast sind sehr viele Lehren über die Seuche festgehalten, die die Geißel über das Land gebracht hat. Wir werden alles eingehend untersuchen. Was Euch betrifft... bitte nehmt dies. Das ist das Mindeste, das wir zum Dank für Eure Mühen tun können." }, enUS = { progress = "On behalf of the Cenarion Circle, I bid you welcome to this enclave, {class}.  What business do you have with us?", completion = "This is from Mulgris, you say?  We had heard he sought to minister to the creatures suffering in the Plaguelands, but this is most unexpected... and most saddening.  Mulgris is... was a good friend.  I will mourn his passing deeply.\n\nHis efforts have not gone in vain, thanks to your diligence.  In this branch, much lore is stored about the plague the Scourge propagates upon the land.  We will study it diligently.  As for you, please accept this.  It is the least we can do for your noble efforts." } })
apply(5001, { "classic", "forever" }, { deDE = { progress = "Glück gehabt?", completion = "Da brat mir doch einer... Wo habt Ihr denn das gefunden???" }, enUS = { progress = "Any luck?", completion = "Well I'll be! Where were they??" } })
apply(5002, { "classic", "forever" }, { deDE = { progress = "Ah, {name}. Wir haben uns lange nicht gesehen.", completion = "Das passt zu einem großen Teil dessen, was wir bereits wissen. Dennoch ist es interessant und höchst unerfreulich.\n\nDie Markierungen auf dieser Karte werden sich bei der Ausdünnung der Blackrockbedrohung als wertvoll erweisen." }, enUS = { progress = "Ah, {name}. It has been a long time.", completion = "This coincides with much of what we already knew. Regardless, it is interesting and rather unfortunate information.\n\nThe markings on this map will prove valuable in thinning the Blackrock menace." } })
apply(5021, { "classic", "forever" }, { deDE = { completion = "Ein Paket in der Scheune, das Ihr sonst übersehen hättet, fällt Euch nun zwischen Zerfall und Ruin ins Auge. Vielleicht ist es das, worüber der Geist von Janice Felstone gesprochen hat..." }, enUS = { completion = "A package in the barn that you might have otherwise overlooked now stands out amongst the decay and ruin.  Perhaps this is the one that the ghost of Janice Felstone was clamoring about..." } })
apply(5022, { "classic", "forever" }, { deDE = { progress = "Willkommen im Volkszählungsbüro von Stormwind. Wenn Ihr Informationen über unsere Bevölkerung benötigt, dann kann ich Euch helfen.", completion = "Ein Paket für eine Emma Felstone, sagt Ihr? Letzte bekannte Adresse war Stormwind, vor vier Jahren? Tja, lasst mich mal nachsehen...\n\nNach dem, was wir wissen, gab es vor ungefähr vier Jahren eine Emma Felstone in der Stadt. Na ja, ich sollte sagen möglicherweise - diese Volkszählung, auf die ich mich beziehe, liegt fünf Jahre zurück und ich habe keinen Bericht darüber, dass sie die Stadt verlassen hat. Das bedeutet aber nicht, dass sie immer noch hier ist.\n\nWartet einen Moment... dieses Paket könnte nicht vielleicht für die alte Emma sein, oder?" }, enUS = { progress = "Welcome to the office of the Stormwind census.  If you are in need of information on our populace, then I can assist you.", completion = "A package for an Emma Felstone, you say?  Last known address was Stormwind, four years ago?  Well let me see here...\n\nAccording to what we know, there was an Emma Felstone in the city about four years ago.  Well, I should say possibly - this census I refer to is from five years ago, and I don't have a report of her vacating the city.  This doesn't mean that she is still here though.\n\nWait a second... this package couldn't be for Ol' Emma, could it?" } })
apply(5023, { "classic", "forever" }, { deDE = { progress = "Seid Ihr hier, weil Ihr die Hilfe des Volkszählungsbüros von Undercity sucht, oder nur, um mich zu fragen, ob jemand, den Ihr kanntet, tot ist? Ich werde das häufig gefragt.", completion = "Ein Paket für einen Jeremiah Felstone, und seine letzte bekannte Adresse war Lordaeron... Ich sollte Euch helfen können.\n\nJeremiah Felstone war vor der Seuche in der Stadt. Tja, ich sollte sagen, der 'ehemalige' Jeremiah Felstone - einige der Verlassenen haben ihren Nachnamen abgelegt, um sich ihrer früheren Identitäten zu entledigen. Dieser Fall ist keine Ausnahme; der ehemalige Jeremiah Felstone ist jetzt unter dem Namen Jeremiah Payson bekannt.\n\nSekunde... ist er nicht der Kakerlakenverkäufer?" }, enUS = { progress = "Are you here to seek the assistance of the Undercity census, or just to ask me if someone you knew is dead?  I get asked that a lot.", completion = "A package for a Jeremiah Felstone, with his last known address as Lordaeron... I should be able to assist you.\n\nJeremiah Felstone was in the city before the plague.  Well, I should say the former Jeremiah Felstone - some of the Forsaken have changed their last names to rid themselves of their former countenance.  This case is no exception; the former Jeremiah Felstone is now known as Jeremiah Payson.\n\nWait a minute... isn't he the cockroach vendor?" } })
apply(5041, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Suche nach den Vorräten, {name}? Ich schätze, die Stacheleber werden unter Eurer Kraft schnell fallen.", completion = "Haha! Danke, {name}! Das wird uns höchst dienlich sein. Ihr seid ein Segen für Crossroads und die Horde. Wenn ich etwas für Euch tun kann, dann lasst es mich bitte wissen." }, enUS = { progress = "How goes your search for the supplies, {name}? I trust the quilboar fall under your strength easily.", completion = "Haha! Thank you, {name}! This will help us greatly. You're a boon to the Crossroads and to the Horde. If there is anything I can do for you, please, let me know." } })
apply(5048, { "classic", "forever" }, { deDE = { progress = "Ich würde Euch sagen, dass Ihr von meinem Grundstück verschwinden sollt, aber wie Ihr seht, habe ich keines.", completion = "Mein Name ist tatsächlich Emma Felstone... Ihr seid seit Jahren die erste Person, die mich so nennt. Wer... wer seid Ihr?\n\nIhr sagt, Ihr kennt... meine Schwester?! Ist sie noch am Leben? Wem mache ich etwas vor, natürlich ist sie es nicht. Als in Lordaeron die Seuche ausbrach, musste ich mit dem Schlimmsten rechnen. So viele aus meiner Familie starben... oder Schlimmeres. Hier bin ich nun, die verrückte alte Emma, ganz allein. Was seid Ihr, ein Grabräuber oder so? Sucht Ihr nach Eurem nächsten Opfer?\n\nWas? Ihr habt ein Paket für mich, von meiner Schwester?" }, enUS = { progress = "I would tell you to get off my lawn, but as you can see I don't have one.", completion = "My name is indeed Emma Felstone - you're the first person in years to call me that.  Who... who are you?\n\nYou say you knew... my sister?!  Is she still alive?  Who am I kidding, of course she isn't.  When the plague broke out in Lordaeron, I had come to expect the worst.  So many of my family died... or worse.  Here I am now, crazy Ol' Emma, all alone.  What are you, a grave-robber or something?  Looking for your next target?\n\nWhat... you have a package for me from my sister?" } })
apply(5049, { "classic", "forever" }, { deDE = { progress = "Jedes Mal, wenn jemand auf eine Kakerlake tritt, muss ich weinen. Bitte, bringt mich nicht zum Weinen.", completion = "Ich habe diesen Namen seit Jahren nicht mehr benutzt... aber ja, an einem gewissen Punkt in meinem Leben - vor diesem glorreichen Unleben - war das mein Nachname.\n\nIhr behauptet, meine Schwester gekannt zu haben... oder vielmehr, kürzlich mit meiner Schwester gesprochen zu haben?\n\nDie ist tot.\n\nSeit vier Jahren.\n\nWisst Ihr, wenn meine Knochen nicht bereits so brüchig wären, wäre ich versucht, mir meinen Fuß an Eurem Hinterteil zu brechen. Ihr seid ein echter Aasgeier, eh?\n\n Was? Ihr habt ein Paket für mich, von meiner Schwester?" }, enUS = { progress = "Every time someone steps on a cockroach, I cry.  Please don't make me cry.", completion = "I haven't used that name in years... but yes, at one point in my life - before this glorious unlife - that was my last name.\n\nYou claim to have known my sister... or rather, have recently spoken to my sister.\n\nWho's been dead.\n\nFor four years.\n\nYou know, if my bones weren't already brittle enough, I'd be tempted to break my foot off on your posterior.  You're quite the vulture, aren't you?\n\n What... you have a package for me from my sister?" } })
apply(5050, { "classic", "forever" }, { deDE = { progress = "John, Liebling... bist du das? Mir ist plötzlich so kalt...", completion = "Ihr gebt den halben Glücksbringer der Erscheinung zurück. Sie sieht erst ihn und dann erwartungsvoll Euch an.\n\n\"Liebling, wo ist deine Hälfte des Glücksbringers? Wir können nur zusammen sein, wenn wir beide Hälften haben. Liebling... kannst du mich sehen?\"" }, enUS = { progress = "John, sweetheart... is that you?  I'm so cold all the sudden...", completion = "You give the half-charm back to the apparition.  She looks at it, then at you expectantly.\n\n\"Honey, where did you put your half of the charm?  We can't be together unless we have both halves.  Honey... can you see me?\"" } })
apply(5051, { "classic", "forever" }, { deDE = { progress = "John, lass dich nicht von den Ghuls erwischen... lass nicht zu, dass die Ghuls mich erwischen... böse Ghuls... unser Glücksbringer wird uns schützen.", completion = "Ihr übergebt den zusammengesetzten Glücksbringer dem Geist von Janice Felstone. Als sie nach ihm greift, geht fast sofort eine Veränderung mit ihr vor. Ihre Astralgestalt schimmert und sie sieht Euch mit klaren, aber traurigen Augen an.\n\n\"Ihr habt mich befreit ... Ich werde diesen Glücksbringer nicht mehr benötigen. Nehmt ihn bitte und vielleicht wird er Euch den Trost geben, den er mir gegeben hat.\"" }, enUS = { progress = "John, don't let the ghouls get you... don't let the ghouls get me... nasty ghouls... our charm will keep us safe.", completion = "You hand the reassembled good luck charm to Janice Felstone's ghost.  As soon as she grasps it, you observe an almost immediate change in her.  Her ethereal form shimmers, and she looks upon you with clear yet sad eyes.\n\n\"You've freed me... I no longer will need this charm.  Please, take it and perhaps it will give you the solace it has given me.\"" } })
apply(5052, { "classic", "forever" }, { deDE = { progress = "Unsere Stämme finden sich in den dornigen Gegenden des Brachlandes zusammen <schnaubt>, da sie heilige Orte sind, aber keiner ist so heilig wie Razorfen. Agammagans Körper bildet die Gesamtheit des Razorfen <schnaubt>, aber die Hügel sind besonders geschützt, da der Eingang aus seinem großen Maul gefertigt ist! <schnaubt> Er wird die mit Haut und Haar verschlingen, die ihm nicht treu ergeben sind, und ihre Körper ausspucken, nachdem er sie zerkaut hat! <schnaubt>\n\nAgammagan hat seinen Körper zurückgelassen, um uns zu schützen, und er gibt uns von seinem Geist, damit wir ihn schützen können. <schnaubt>", completion = "Ah, Ihr versteht also. <schnaubt> Meine Worte waren in Euren Ohren nicht verloren, {race}. Quetschzahn mag eingekerkert sein, aber kein Käfig kann Agammagans Macht stoppen! \n\nDie Berührung des Splitters, das Gefühl... es ist schon lange her, {race}.\n\nWisst Ihr, wie es ist? Wenn man seiner Macht beraubt wird?\n\nAber das ist eine andere Geschichte. Ich habe Euch Informationen versprochen. Ich habe Euch Agammagans Macht versprochen. Meine Leute haben Quetschzahn den Rücken zugewandt. Nun lasse ich Euch auf sie los." }, enUS = { progress = "Our tribes flock to the thorny areas throughout the Barrens <snort> because they are holy places, but none as holy as Razorfen. Agamaggan's body makes up the entirety of the Razorfen, <snort> but the Downs are especially protected because the entrance is made from his great maw! <snort> It will swallow whole those not loyal to him, and spit out their bodies after he's chewed them up! <snort>\n\nAgamaggan has left his body behind to protect us, and he gives of his spirit so we may protect him. <snort>", completion = "Ah, you do understand. <snort> My words were not lost on your ears, {race}. Mangletooth may be caged, but no cage can stop Agamaggan's power! \n\nThe touch of the shard, the feel of it... it has been a long time, {race}.\n\nDo you know what it is like? To have your power severed from you?\n\nBut, that is a tale for another time. I promised you information. I promised you Agamaggan's power. My people turned their backs on Mangletooth. Now, I lose you upon them." } })
apply(5057, { "classic", "forever" }, { deDE = { completion = "Wir lernen aus den Erfahrungen unseres Lebens, {name}. Ich bin sicher, dass Ihr durch die Euren nur stärker und weiser geworden seid. Ihr seid innerlich gewachsen, seitdem wir das letzte Mal miteinander gesprochen haben.\n\nNehmt dies als Erinnerung an die schwierigen Aufgaben, die Ihr als {class} bewältigt habt, {race}, und wisset, dass Euch mein Respekt und meine Bewunderung immer sicher sein werden." }, enUS = { completion = "We learn from our life experiences, {name}. I am sure that you have only become stronger and wiser as a result of yours. You have grown much since we first spoke.\n\nTake this in remembrance of the difficult tasks you have accomplished as a {race} {class}, and know that you will always have my respect and admiration." } })
apply(5061, { "classic", "forever" }, { deDE = { progress = "Eure Rückkehr nach Darnassus kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, {name}. Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen." }, enUS = { progress = "Your return to Darnassus is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.\n\nDo you have the Pendant of the Sea Lion?", completion = "Very impressive, {name}.  You are ready to learn your aquatic form, and it is my pleasure to teach it to you.\n\nAlso, in recognition of your achievement during the two trials, I give you this item.  I hope you'll find it to be a welcome addition to your gear as a protector of nature and a keeper of the balance." } })
apply(5062, { "classic", "forever" }, { deDE = { progress = "So, Motega Firemane schickt Nachricht von Arikara... nun, das sind böse Neuigkeiten.\n\n<Magatha sieht sich um.>\n\nArikara ist eine tödliche Kreatur, die nur geboren wurde, um Rache gegen die zu suchen, die ruchlose Taten begangen haben.\n\n<Magatha lächelt.>", completion = "Gut, Ihr habt die benötigte Menge Brandpulveragaven gesammelt. Dieses seltene Kraut, das man nur in Tausend Nadeln findet, wird helfen, das schlafende hochheilige Feuer des Lebens zu erwecken.\n\n<Magatha beginnt, die Brandpulveragaven zu verzaubern.>" }, enUS = { progress = "So, Motega Firemain sends word of Arikara...well now that is grave news.\n\n<Magatha looks around.>\n\nArikara is a deadly creature born only to seek vengeance against those who have committed heinous acts.\n\n<Magatha smiles.>", completion = "Good, you have gathered the essential amount of Incendia agave. This rare herb found only in Thousand Needles will help light the dormant sacred fire of life.\n\n<Magatha begins to enchant the Incendia agave.>" } })
apply(5064, { "classic", "forever" }, { deDE = { progress = "Habt Ihr entdeckt, was die Grimmtotem vorhaben?", completion = "Großes Geistertotem! Das sind wahrlich schlimme Neuigkeiten. Ich muss für alle nur möglichen Fälle Pläne entwickeln.\n\n{name}, wie versprochen ist hier Eure Belohnung für Euren mutigen Dienst." }, enUS = { progress = "Have you discovered what the Grimtotem are up to?", completion = "Great Spirit Totem! This is dire news indeed. I must begin to plan for whatever may come.\n\n{name}, as promised, here is your reward for your brave service." } })
apply(5065, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schrifttafeln? Ich fürchte, dass ihre Texte eine große Bedrohung für unsere Welt enthüllen werden.", completion = "Ihr habt sie gefunden! Großartig!\n\nIch danke Euch, {name}. Ich werde diese Texte durchgehen und ihre Bedeutung entschlüsseln.\n\nIhr aber habt eine andere Aufgabe..." }, enUS = { progress = "Do you have the tablets?  I fear their texts will reveal a great threat to our world.", completion = "You found them!  Great!\n\nThank you, {name}.  I will pour over these texts and decipher their meaning.\n\nYou, however, have another task..." } })
apply(5066, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5081, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Zumindest habt Ihr uns mehr Zeit verschafft - äußerst wertvolle Zeit." }, enUS = { completion = "Excellent work, {name}. At the very least, you have bought us more time - precious, precious time." } })
apply(5082, { "classic", "forever" }, { deDE = { completion = "Ich danke Euch vielmals, {name}! Jetzt kann ich mich hier wieder an die Arbeit machen.\n\nHabt Ihr im Lager der Winterfelle irgendetwas Interessantes gefunden?" }, enUS = { completion = "Thanks so much, {name}! Now I can get back to work here.\n\nDid you find anything of interest at the Winterfall camp?" } })
apply(5083, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr da gefunden?", completion = "Ihr habt dies von den Winterfellfurbolgs?" }, enUS = { progress = "What is that you have found?", completion = "You got this from the Winterfall?" } })
apply(5084, { "classic", "forever" }, { deDE = { completion = "Im Kessel blubbert eine faulige, ekelerregend riechende Substanz..." }, enUS = { completion = "Inside the cauldron bubbles a rotting, repulsive-smelling substance..." } })
apply(5085, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr habt etwas gefunden, {name}. Die Winterfelle werden immer aggressiver!", completion = "Ihr seid sehr einfallsreich, {name}. Glaubt Ihr, dass die Furbolgs der Winterfelle im Lager der Totenwaldfelle waren?" }, enUS = { progress = "I hope you found something, {name}. The Winterfall are becoming increasingly aggressive!", completion = "You are very resourceful, {name}. Do you think that the Winterfall furbolgs have been to the Deadwood camp?" } })
apply(5086, { "classic", "forever" }, { deDE = { progress = "Ich glaube, wir verstehen so langsam, was hier geschieht, {name}.", completion = "Ich muss diese Substanz mit der vergleichen, die Ihr in dem Kessel gefunden habt, und dann werden wir sicherlich mehr wissen." }, enUS = { progress = "I think we are beginning to uncover what is happening here, {name}.", completion = "I have to compare this to the substance you found in the cauldron, and then I'm sure we'll know more." } })
apply(5087, { "classic", "forever" }, { deDE = { progress = "Wir werden ja sehen, was geschieht, wenn die Winterfelle ihr Feuerwasser nicht bekommen!", completion = "<Donova untersucht den Inhalt der Kiste.>\n\nIch frage mich, ob der Verzehr dieser Substanz die Furbolgs aggressiver macht. Sie wirken irgendwie viel größer..." }, enUS = { progress = "We'll see what happens when the Winterfall don't get their firewater!", completion = "<Donova examines the contents of the crate.>\n\nI wonder if consuming this substance makes the furbolg more aggressive. They do seem much larger..." } })
apply(5088, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die heimtückische Schlange Arikara erschlagen, {name}?", completion = "Das ergibt keinen Sinn. Warum sollte Arikara hinter Cairne Bloodhoof her sein? Magatha kann sich nicht irren, sie ist unsere mächtigste Schamanin.\n\n<Motega schüttelt seinen Kopf.>\n\nWie dem auch sei, Eure große Tat für die Horde soll nicht unbemerkt bleiben - wählt bitte einen dieser Gegenstände als Belohnung für Eure Hilfe." }, enUS = { progress = "Have you slain the vicious serpent Arikara, {name}?", completion = "This does not make sense. Why would Arikara be after Cairne Bloodhoof? Magatha could not be wrong, she is our most powerful shaman.\n\n<Motega shakes his head.>\n\nRegardless, your great deed to the Horde shall not go unnoticed - please, choose one of these as a reward for your aid." } })
apply(5089, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da, {name}?", completion = "Es wird spannend..." }, enUS = { progress = "What have you got there, {name}?", completion = "The plot thickens..." } })
apply(5090, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5091, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast.  I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5092, { "classic", "forever" }, { deDE = { completion = "Mission erfüllt, {name}! Das war sehr gut gespielt.\n\nErlaubt mir, Eure bisherige Arbeit mit einigen Münzen aus dem Staatsschatz von Stormwind zu belohnen. Ich empfehle Euch, es für Material auszugeben, das Euch bei der nächsten Mission helfen wird... einer, die Euch in die Ruinen von Andorhal hineinführen wird.\n\nSeid bereit! Seid wachsam!" }, enUS = { completion = "Mission accomplished, {name}!  Well played, well played.\n\nAllow me to reward your work thus far with some coin from the Stormwind coffers.  I'd recommend spending it on materiel that will aid you in your next mission... one that will take you into the ruins of Andorhal itself.\n\nBe ready!  Be vigilant!" } })
apply(5093, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there.  I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5094, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there.  I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5095, { "classic", "forever" }, { deDE = { completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun." }, enUS = { completion = "Welcome to the Plaguelands, hero.  This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there.  I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." } })
apply(5096, { "classic", "forever" }, { deDE = { progress = "Ein Überraschungsangriff auf die schwache Vorhut des Scharlachroten Kreuzzugs wird uns genügend Zeit verschaffen, um gen Andorhal zu marschieren. Ich erwarte, dass Ihr von Eurem Erfolg berichten wollt!\n\nNachdem dies erfolgreich ausgeführt ist, müssen wir sorgfältig und schnell sein. Wir haben weder das Material noch die Männer, um sowohl die Geißel als auch den Scharlachroten Kreuzzug gleichzeitig zu bekämpfen, wenn sie unserem kleinen Trick nicht glauben.", completion = "Das habt Ihr hervorragend gemacht, {name}! Euer Angriff auf den Scharlachroten Kreuzzug wird uns Zeit verschaffen. Ich habe einen meiner besten Späher geschickt, um das Lager zu beobachten und sicherzustellen, dass die Kräfte des Kreuzzugs, die zur Verstärkung der Position anrücken, den Köder schlucken.\n\nNachdem sich der Druck auf uns verringert hat, sollten wir dann eine Mission nach Andorhal riskieren können und eine wichtige noch dazu. Ich möchte gern, dass Ihr auch diese ausführt, da Ihr bisher so erfolgreich wart." }, enUS = { progress = "A surprise raid on the Scarlet Crusade's tenuous forward position will give us a buffer of time to be able to march on Andorhal.  I trust you are here to report success!\n\nOnce this is successfully executed, we will need to work diligently and quickly.  We do not have the materiel and manpower to fight both the Scourge and the Scarlet Crusade at the same time if they do not buy our little ruse.", completion = "Finely executed, {name}.  Your attack on the Scarlet Crusade will buy us time.  I have sent one of my best scouts out to watch over the camp and make sure that the Crusade forces that come to reinforce the position will take the bait.\n\nWith the pressure on us lessened, we should now finally be able to risk a mission into Andorhal itself, and an important one at that.  I'd very much like it if you'd perform this one as well, based on your success to date." } })
apply(5097, { "classic", "forever" }, { deDE = { progress = "Wenn die Türme markiert sind, werden sie zu Zielen der obersten Priorität für unseren Angriff auf Andorhal. Ich vermute, dass die Hauptbedrohung von Andorhal auftauchen wird, wenn wir die Türme neutralisiert haben. Von dem Punkt an gibt es einen offenen Kampf um die Kontrolle der Stadt!\n\nIhr seid zurück, um von Eurem Erfolg zu berichten, ja? Vergesst nicht die Signalfackel, wir müssen die Kontrolle über unser Material bewahren.", completion = "Meine Priester melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ich wage zu sagen, dass Ihr eine weitere Mission mit umfassendem und absolutem Erfolg ausgeführt habt! Erneut gut gespielt, {name}!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!" }, enUS = { progress = "Once the towers are marked, they'll become top priority targets for our attack on Andorhal.  I suspect that once we neutralize the towers, the main threat of Andorhal will emerge.  From that point on, we'll have a straight-up fight for control of the city!\n\nYou're back to report success, yes?  Don't forget the beacon torch as well; we must maintain control of our materiel.", completion = "My priests are reporting that our beacon trackers are picking up extremely strong signals on all four towers!  Dare I say it, but I believe you've executed another mission with complete and total success!  Well played once again, {name}!\n\nWith the towers marked, our preparations for the attack are now in place.  The time has come to take the fight to the Scourge!" } })
apply(5098, { "classic", "forever" }, { deDE = { completion = "Meine Hexenmeister melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ihr habt meine Befehle mit dem Geschick und der Präzision eines erfahrenen Veterans ausgeführt. Euer Dienst an der Horde wird einmal mehr aufmerksam notiert, {name}!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!" }, enUS = { completion = "My warlocks are reporting that our beacon trackers are picking up extremely strong signals on all four towers!  You've executed my orders with the skill and precision of a seasoned veteran.  Your service to the Horde is duly noted once more, {name}!\n\nWith the towers marked, our preparations for the attack are now in place.  The time has come to take the fight to the Scourge!" } })
apply(5102, { "classic", "forever" }, { deDE = { completion = "Wir werden bestimmt als Nächstes gegen ihre Großdrachenlords ziehen. Gut gemacht, mutiger Soldat der Allianz! Wirklich hervorragend." }, enUS = { completion = "Surely, we will strike against their dragon lords next. Well done, brave soldier of the Alliance! Well done, indeed." } })
apply(5103, { "classic", "forever" }, { deDE = { completion = "Was zum..." }, enUS = { completion = "What the..." } })
apply(5121, { "classic", "forever" }, { deDE = { completion = "Vielen herzlichen Dank, {name}. Ich hoffe zu meinen Studien zurückkehren zu können, ohne Angst, dass ich in einen Hinterhalt gerate. Nehmt dies bitte als Belohnung." }, enUS = { completion = "Thank you so much, {name}. I hope to get back to my studies without worry that I will be ambushed. Please accept this as a reward." } })
apply(5123, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr da, {name}?", completion = "Ich frage mich, was das alles bedeutet... Ich kann mir keinen Reim darauf machen..." }, enUS = { progress = "Now, what's this, {name}?", completion = "I wonder what all of this means... I can't make anything out..." } })
apply(5124, { "classic", "forever" }, { deDE = { progress = "Zeit ist Geld, {name}, und ich habe von beidem nicht viel.", completion = "Wie versprochen, {name}, hier ist Euer Rezept! Ich werde Euch für Eure harte Arbeit und Hingabe außerdem noch etwas extra geben. Was sollte ich sonst mit dem Zeug hier tun..." }, enUS = { progress = "Time is money, {name} and I don't have much of either.", completion = "As promised, {name}, here's your recipe! I'm also going to throw in a little something extra for all of your hard work and dedication. What am I going to do with these anyway???" } })
apply(5126, { "classic", "forever" }, { deDE = { completion = "<Lorax lacht.>" }, enUS = { completion = "<Lorax laughs.>" } })
apply(5127, { "classic", "forever" }, { deDE = { progress = "Seid nicht versucht...", completion = "Unseren Pakt habt Ihr nicht gebrochen. Die Seele nahm ich. Die Belohnung werde ich geben." }, enUS = { progress = "Tempt not...", completion = "Our pact you did not break. The soul I did take. The reward I shall make." } })
apply(5128, { "classic", "forever" }, { deDE = { progress = "Der Smaragdkreis ist allen freundlich gesinnt, {race}. Was kann ich für Euch tun?", completion = "Ja, wenn Ihr es mich eine Weile untersuchen lasst, kann ich es für Euch vielleicht übersetzen.\n\n<Kelek blättert durch die Seiten.>\n\nWenn ich es ganz durchgesehen habe, werde ich Euch eine Nachricht schicken.\n\nDanke, dass Ihr dies mit mir teilt, {name}. Man weiß sehr wenig über die Winterfellfurbolgs." }, enUS = { progress = "The Emerald Circle is friendly to all, {race}. What can I do for you?", completion = "Yes, if you let me examine this for a while, I might be able to translate it for you.\n\n<Kelek flips through the pages.>\n\nWhen I am able to look over this fully, I will send word to you.\n\nThank you for sharing this with me, {name}. Very little is known about the Winterfall furbolg." } })
apply(5141, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst." }, enUS = { progress = "If you're ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I'm ready to take you on as a student.  Just bring to me the things I asked for, and we'll begin your education.", completion = "I'll hand it to you - it takes a strong will to make a permanent decision like you've just done.  I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours." } })
apply(5142, { "classic", "forever" }, { deDE = { completion = "Hallo. Ich bin Pamela, und wie heißt Ihr?" }, enUS = { completion = "Hello.  I'm Pamela, what's your name?" } })
apply(5143, { "classic", "forever" }, { deDE = { progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst." }, enUS = { progress = "Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments.  Bring me your offering to this force, and I will make sure you are heard.", completion = "You've given your finest offerings, and nature will soon permit you to bend her to your will.  Once I have finished my tutelage, your work will be a force of nature unto itself.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours." } })
apply(5145, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe, und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst." }, enUS = { progress = "If you're ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I'm ready to take you on as a student.  Just bring to me the things I asked for, and we'll begin your education.", completion = "I'll hand it to you - it takes a strong will to make a permanent decision like you've just done.  I assure you, dragonscale leatherworking will prove to be a profitable and rewarding path for you to follow.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours." } })
apply(5147, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Neuigkeiten über diesen mordlustigen Arnak Grimmtotem?", completion = "Ha! Na, das sind doch ausgezeichnete Neuigkeiten! Ich dachte langsam, er würde nie der Gerechtigkeit zugeführt werden!\n\nHier, bitte schön, {name}... und vielen Dank. Die Neuigkeiten von Arnaks widerlichen Taten brachten mein Blut zum Sieden!" }, enUS = { progress = "Have you any news of that murderous Arnak Grimtotem?", completion = "Hah! Well, this is excellent news! I was starting to think that he would never be brought to justice!\n\nHere you are, {name}... and thanks. News of Arnak's foul deeds boiled my blood!" } })
apply(5148, { "classic", "forever" }, { deDE = { progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst." }, enUS = { progress = "Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments.  Bring me your offering to this force, and I will make sure you are heard.", completion = "You've given your finest offerings, and nature will soon permit you to bend her to your will.  Once I have finished my tutelage, your work will be a force of nature unto itself.\n\nTo train in the art for the future, simply speak to me and I will make available any knowledge that you have yet to commit as yours." } })
apply(5149, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!" }, enUS = { progress = "Did you find my doll?", completion = "You found it!  You found my doll!  Oh, thank you!" } })
apply(5151, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen Hyperkondensator?", completion = "Mein Hyperkondensator! Damit werde ich einige Zeit beschäftigt sein, bis ich herausgefunden habe, was er macht..." }, enUS = { progress = "Do you have my hypercapacitor?", completion = "My hypercapacitor! This will keep me busy for a while until I can figure out what it does..." } })
apply(5152, { "classic", "forever" }, { deDE = { completion = "Ihr habt Pamela gesehen? Wie geht es ihr? Ist sie am Leben?? Oh nein! Die arme Pamela! Sie war so jung und so ein fröhliches Kind...\n\nSie weiß nicht, was mit ihrem Vater geschehen ist, nicht wahr? Mit meinem Bruder Joseph...\n\nNein... sie könnte nicht verstehen, was mit Joseph geschehen ist. Und selbst wenn sie es könnte, ich habe nicht das Herz, es ihr zu sagen..." }, enUS = { completion = "You saw Pamela?  How is she?  Is she alive??  Oh, no!  Poor Pamela!  She was so young, and such a happy child...\n\nShe doesn't know what happened to her father, does she?  My brother, Joseph?\n\nNo... she couldn't understand what happened to Joseph.  And even if she could, I don't have the heart to tell her..." } })
apply(5153, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen guten Zeitpunkt für Euren Besuch gewählt. Ihr seid nicht zufälligerweise aus der Zukunft, oder?", completion = "Was ist das? Ein Ehering? Lasst mich mal sehen...\n\nAh! Dieser Ring steckte einst an der Hand eines großen Mannes, aber in der Vergangenheit dieses Mannes geschah eine große Tragödie.\n\nSeid Ihr hier, um ihm zu helfen? Für ihn ist jetzt alles zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!" }, enUS = { progress = "There is something timely about your visit.  You're not from the future, are you?", completion = "What is this?  A wedding ring?  Let me see...\n\nAh!  This ring was once on the hand of a great man, but there is much tragedy in that man's past.\n\nAre you here to help him?  It's far too late for him now... but perhaps we can help him in the past!" } })
apply(5154, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Buch gefunden, {name}?", completion = "Sehr schön, Ihr habt es gefunden!\n\nHabt Ihr es gelesen? Wird Joseph Redpath erwähnt? Falls er erwähnt wird, dann können wir ihn vielleicht retten!\n\nAh. Die 'Annalen von Darrowshire' erzählen eine sehr beunruhigende Geschichte. Darin heißt es, dass Joseph Redpath während des Kampfes verderbt wurde und sich in die Ränge der Geißel eingereiht hat! Dann verriet er die Verteidiger von Darrowshire.\n\nDas ist ein übles Schicksal. Wir sollten versuchen, dieses Schicksal zu ändern, so das möglich ist, meint Ihr nicht?" }, enUS = { progress = "Did you find the book, {name}?", completion = "Well done, you found it!\n\nDid you read it?  Is Joseph Redpath mentioned?  If he is, then perhaps we can save him!\n\nAh.  The Annals of Darrowshire tell a very unsettling tale.  It says that during the battle, Joseph Redpath was corrupted and joined the ranks of the Scourge!  He then betrayed the defenders of Darrowshire.\n\nThat is an ill fate.  If we can, we should try to change that fate, don't you think?" } })
apply(5155, { "classic", "forever" }, { deDE = { completion = "Gut, {name}! Wenn ihre Anzahl abgenommen hat, können wir sie weiter bedrängen.\n\nWie war Euer erster Eindruck ihrer Macht? Waren sie so stark, wie ich dachte? Stärker? Oder vielleicht waren sie überhaupt keine Herausforderung für Euch... Das wäre nun wirklich eine Überraschung!\n\nWir können die Einzelheiten Eurer Taten später erörtern. Jetzt müssen wir uns auf andere Dinge konzentrieren." }, enUS = { completion = "Good, {name}! With their numbers weakening, we can further press them.\n\nHow was your first taste of their power? Were they as strong as you thought they would be? Stronger? Or perhaps they were no challenge for you at all. Wouldn't that be something?\n\nWe can discuss the details of your exploits later. There are other things we must focus on now." } })
apply(5156, { "classic", "forever" }, { deDE = { completion = "Schön, dass Ihr am Leben seid, {name}. Nicht schön ist, dass das Wasser immer noch existiert. Ich hatte gehofft, zumindest eine reine Wasserquelle hier im Teufelswald zu finden. Es sieht so aus, als wäre meine Suche fehlgeschlagen. Gäbe es sie, wäre der Prozess der Heilung des Landes wesentlich vereinfacht worden.\n\nIch werde mich also damit befassen müssen, die Waldkreaturen zu retten, die ich retten kann. Gleichzeitig vernichte ich die, die so verderbt wurden, dass sie nicht nur für sich selbst, sondern auch für Reisende, die durch diesen einst so mächtigen Wald ziehen, eine Gefahr sind." }, enUS = { completion = "Good that you're alive, {name}. Bad that the water still exists. I was hoping to find at least one pure source of water here in Felwood. It looks like my search has failed. The process of healing the land could have been made much easier with its existence.\n\nI will have to concern myself with saving what forest creatures I can while destroying those that have become so corrupt that they endanger themselves as much as travelers through this once-mighty forest." } })
apply(5157, { "classic", "forever" }, { deDE = { progress = "Wenn wir Wasser vom Mondbrunnen haben, werden wir es läutern und dazu verwenden, die Kohlenpfannen des Schutzes in der Schattenfeste zu löschen. Das würde mir ausreichend Zeit geben, um noch tiefer in die Kammern hineinzusehen und zu erkennen, wer diesen ... Kult tatsächlich anführt.\n\nIch bete, dass die Erdenmutter mit uns ist.", completion = "Das dürfte reichen, {name}.\n\nJetzt müssen wir das Wasser nur noch läutern lassen, bevor wir es auf die Kohlenpfannen anwenden. Das sollte nicht schwierig sein - es ist nur eine kleine Reise dafür erforderlich.\n\nHoffentlich können wir das schnell erledigen." }, enUS = { progress = "Once we have the waters from the Moon Well, we will purify it and use it to extinguish the braziers of protection within Shadow Hold. That should allow me ample time to see into the chambers even deeper and discern who actually leads this... cult.\n\nI pray the Earthmother is with us.", completion = "This will do nicely, {name}.\n\nNow all we have to do besides apply the waters to the braziers is to have it purified. That should not be difficult--it should only require a little travel.\n\nHopefully we can do this quickly." } })
apply(5158, { "classic", "forever" }, { deDE = { progress = "Ich spüre, dass Ihr nicht nur ein einfacher Reisender seid, der den Weg nach Ratchet sucht. Kommt, setzt Euch und ruht Euch in unserem Lager aus. Sprecht mit mir, wenn Ihr bereit seid.", completion = "Ah, Ihr müsst das Wasser aus diesem Mondbrunnen säubern lassen. Es erscheint edel genug, die Kräfte der Bosheit im Teufelswald stoppen zu wollen, aber die Entscheidung liegt nicht bei mir, ob dieses Wasser geläutert wird. Ich werde die Geister des Wassers fragen - es wird an ihnen liegen zu entscheiden, ob der Grund gerecht ist.\n\nGebt mir einen Augenblick und ich werde ihnen von Eurer Bitte berichten. Ich hoffe, dass sie Eurem Anliegen genauso wohlwollend gegenüberstehen wie ich." }, enUS = { progress = "I sense you are not just a simple traveler looking for the path to Ratchet. Come, sit and rest at our camp. Speak to me when you're ready.", completion = "Ah, you need the water from this Moon Well cleansed. Stopping this force of malice in Felwood seems noble enough, but it is not for me to decide if the water will be purified. I will ask the spirits of water--it will be up to them to decide if the cause is just.\n\nGive me a moment and I will tell them of your plea. I hope they are as sympathetic as I am to your cause." } })
apply(5159, { "classic", "forever" }, { deDE = { progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt, {name}. Gut. Habt Ihr Islen im Brachland gefunden? Oder müssen wir einen anderen Weg finden, unsere Ziele zu erreichen?", completion = "Das sollte mehr als genug Wasser für unsere Zwecke sein.\n\nIch freue mich zu hören, dass Islen uns helfen konnte. Ihre Kraft mit den Wassergeistern war immer stark. Außerdem ist sie weise und es kommt selten vor, dass die Geister ihre Absichten nicht gutheißen. Die Tatsache, dass beide unsere Aufgabe abgesegnet haben, gibt mir die Hoffnung, dass wir auf dem rechten Weg sind." }, enUS = { progress = "Ah, I see you've returned, {name}. Good. Did you find Islen in the Barrens? Or do we have to find another way to accomplish our goals?", completion = "This should be more than enough water for our purposes.\n\nI'm glad to hear that Islen was able to help us. Her strength with the water spirits has always been a strong one. She is also wise, and rare is it that the spirits do not agree with her purpose. The fact that both of them have blessed our task gives me hope that we are on the right path." } })
apply(5160, { "classic", "forever" }, { deDE = { progress = "Es ist schön, Euch zu sehen, {name}.", completion = "Die Aspekte bestehen darauf, dass wir uns aus den Angelegenheiten der Sterblichen heraushalten. In dieser Welt ist das aber nicht immer möglich - besonders, wenn einer der Unseren solche Erlasse verächtlich missachtet." }, enUS = { progress = "It is good to see you, {name}.", completion = "The Aspects insist that we stay out of the affairs of mortals. In this world, however, such a thing is not always possible - especially when one of our own contemptuously disregards such edicts." } })
apply(5161, { "classic", "forever" }, { deDE = { completion = "So soll es geschehen..." }, enUS = { completion = "So it shall be..." } })
apply(5162, { "classic", "forever" }, { deDE = { completion = "Ich bin Jeziba, vielen bekannt als der Bildhauer. Was ich forme, sind aber keine Statuen, sondern Helden." }, enUS = { completion = "I am Jeziba, known to many as the Sculptor. What I sculpt, however, are not statues, but heroes." } })
apply(5163, { "classic", "forever" }, { deDE = { progress = "Ich kann es gar nicht erwarten zu hören, wie meine Freunde reagieren!\n\nDas werden sie niemals erwarten!", completion = "Ha! Die werden es sich jetzt zweimal überlegen, bevor sie sich wieder über meine Ideen lustig machen!\n\nIch danke Euch für Eure Hilfe, {name}. Ohne Euch hätte ich nicht so viel Spaß haben können!" }, enUS = { progress = "I can't wait to hear how my friends react!\n\nThey'll never expect it!", completion = "Hah! They'll think twice before making fun of my ideas again!\n\nThanks for your help, {name}. I couldn't have had so much fun without you!" } })
apply(5164, { "classic", "forever" }, { deDE = { completion = "Hunderte und Hunderte von Seiten voller Textfetzen und Symbole bilden den Großteil dieses Buches." }, enUS = { completion = "Hundreds upon hundreds of pages filled with garbled text and symbols make up the brunt of this book." } })
apply(5165, { "classic", "forever" }, { deDE = { completion = "Ich konnte Euch durch meine Zauber sehen, als die Flamme der letzten Kohlenpfanne erstarb. Gut gemacht, {name}.\n\nIch habe einige Dinge in Erfahrung gebracht, bevor die Hexenmeister des Schattenrates ihre Zauber erneut wirken konnten. Hoffentlich wird es ausreichen.\n\nNun denn, ruht Euch aus. Ich werde Euch dann berichten, was ich erfahren habe." }, enUS = { completion = "I was able to see you with my spells as soon as the last brazier's flames died. Well done, {name}.\n\nI learned a few things before the Shadow Council's warlocks were able to recast their spells. Hopefully it will be enough.\n\nFor now, rest. I will tell you what I've learned in a moment." } })
apply(5166, { "classic", "forever" }, { deDE = { progress = "Ihr habt weise gewählt, {race}.", completion = "Habt Ihr noch immer nicht verstanden? Die Reise war das Ziel. Könnt Ihr nicht die Narben des Kampfes fühlen? Den Schmerz, den Ihr ertragen habt?\n\nDa Ihr die Tortur überlebt habt, seid Ihr nun ein mächtigeres Wesen. Viel mächtiger. Diese Brustplatte ist nur ein Spiegelbild Eurer eigenen angeborenen Fähigkeiten." }, enUS = { progress = "You have chosen wisely, {race}.", completion = "Do you not yet understand? The journey was the destination. Can you not feel the battle scars? The pain you underwent?\n\nHaving survived the ordeal, you are a more powerful being. Much more powerful. This breastplate is merely a reflection of your own innate abilities." } })
apply(5168, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Relikte, {name}?", completion = "Ihr habt den Buchband und den Schild!\n\nIhre Geschichte ist mit der Geschichte von Darrowshire verbunden und irgendwie weiß ich, dass das Schicksal sie wieder zusammenführen wird." }, enUS = { progress = "Do you have the relics, {name}?", completion = "You have the libram and the shield!\n\nTheir history is entwined with the history of Darrowshire, and somehow, I know that fate will bring them together again." } })
apply(5181, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Schädel und das Schwert gefunden, {name}?", completion = "Ihr habt sie gefunden! Gut gemacht, {name}! Diese Relikte enthalten eine Macht, die ich nicht ganz verstehe, eine Macht, die Ihr eines Tages beherrschen werdet.\n\nSie wecken aber auch dunkle Erinnerungen in meinen Gedanken, Erinnerungen an Tod und Verrat und an die letzte Nacht von Darrowshire..." }, enUS = { progress = "Did you find the skull and the sword, {name}?", completion = "You found them!  Well done, {name}!  These relics hold a power I do not fully understand, a power you will one day harness.\n\nThey also bring dark memories to my mind, memories of death and treachery, and of the last night of Darrowshire..." } })
apply(5201, { "classic", "forever" }, { deDE = { completion = "Ich bin erleichtert zu hören, dass wir uns zumindest für kurze Zeit über die Eindringlinge der Winterfelle keine Sorgen machen müssen.\n\nIhr beginnt Beharrlichkeit zu zeigen, {name}." }, enUS = { completion = "I am relieved to hear that for a short moment, we will not have to worry about the Winterfall intrusion.\n\nYou are beginning to show your perseverance, {name}." } })
apply(5202, { "classic", "forever" }, { deDE = { progress = "Ich beginne mich zu fragen, ob ich diesem Käfig jemals entkommen werde.\n\nEs ist nur eine Frage der Zeit, bevor sie mich irgendeinem der Dämonen opfern, die sie anbeten. Diese Monster!", completion = "Der Schlüssel, Ihr habt ihn gefunden! Bitte, gebt ihn mir, damit ich endlich entkommen kann!" }, enUS = { progress = "I begin to wonder if I'll ever escape this cage.\n\nIt's only a matter of time before they sacrifice me to whatever demons they worship. The monsters!", completion = "The key, you've found it! Please, give it to me and I can finally escape!" } })
apply(5203, { "classic", "forever" }, { deDE = { completion = "Ihr wart es, der Arko bei der Flucht geholfen hat? Ich bin ja so froh, dass Ihr mich gefunden habt. Sie kam vor nicht allzu langer Zeit auf ihrem Weg nach Darnassus hier vorbei. Sie hatte Lightforge im Schlepptau und nahm sich nicht einmal die Zeit, um mit den Druiden zu sprechen, um sich heilen zu lassen. Sie sagte, es wäre viel zu dringend.\n\nAber sie berichtete mir von Eurer Begegnung mit dem Geist von Trey. Was für ein schreckliches Schicksal für einen Ritter der Silberhand. Sie zeigte es nicht, aber ich weiß, dass der Gedanke, einen ihrer engsten Freund zu verlieren, sie im Inneren zerreißt." }, enUS = { completion = "You were the one who helped Arko escape? I'm so glad you found me. She passed by here not too long ago on her way to Darnassus. She had Lightforge in tow and wouldn't even take time to speak to the druids to be healed. She said it was far too urgent.\n\nBut she did tell me about your encounter with Trey's spirit. What a terrible fate for a Knight of the Silver Hand. She didn't show it, but I know it's tearing her up inside, the thought of losing one of her closest friends." } })
apply(5204, { "classic", "forever" }, { deDE = { progress = "Ihr untersucht den Körper und es gibt keinen Zweifel, dass dies die Überreste des Ritters der Silberhand, Trey Lightforge, sind. Einen Moment lang denkt Ihr an Arko'narin und fragt Euch, ob Euch jemals in Eurem Leben jemand so viel bedeutet hat, wie dieser Mann der gefangenen Nachtelfin bedeutete, der Ihr kürzlich bei der Flucht aus der Schattenfeste geholfen habt.\n\nNachdem Ihr in einem weiteren Augenblick Eure Gedanken gesammelt habt, wisst Ihr, dass Ihr die Überreste des Paladins nicht zu Jessir zurückbringen könnt, ohne zuvor seinen Folterknecht zu töten.", completion = "Ihr sammelt die Überreste des Paladins so sorgfältig wie möglich ein und erinnert Euch daran, dass zumindest sein Geist von jeglichem Schmerz oder Leiden erlöst wurde, das über ihn gebracht worden war." }, enUS = { progress = "You inspect the body, and there is no doubt that these are the remains of the Knight of the Silver Hand, Trey Lightforge. For a moment you think of Arko'narin and question if anyone in your life meant as much to you as this man meant to the Night elf captive you recently helped escape Shadow Hold.\n\nAfter taking another moment to gather your thoughts, you know that you cannot take the paladin's remains back to Jessir without killing his torturer first.", completion = "You gather the paladin's remains as carefully as you can, recalling that at least his spirit has been released from any pain or suffering that might have been forced upon him." } })
apply(5206, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schädel? Chromie sagte, sie wären äußerst wichtig für ihren Zauber, und dieser Zauber gäbe uns die Chance, Darrowshire zu retten.", completion = "Ihr habt sie gefunden! Großartig!\n\nWenn ich auch nicht genau weiß, inwiefern sie uns helfen werden, so spüre ich doch ihre Macht und fühle es in meinen Knochen, dass sie irgendwie mit meinem Heimatdorf Darrowshire verbunden sind." }, enUS = { progress = "Do you have the skulls?  Chromie said they will be critical for her spell, and that spell will give us the chance to save Darrowshire.", completion = "You found them!  Wonderful!\n\nAlthough I don't fully understand how they can help us, I feel their power and I know in my bones that they are linked to my home village of Darrowshire." } })
apply(5210, { "classic", "forever" }, { deDE = { progress = "Ihr kommt aus dem Westen? Wie ergeht es dem Rest von Lordaeron? Ich weiß, dass Andorhal verloren ist, aber hat die Geißel schon Tirisfal erreicht?", completion = "Was ist mit diesem Buch? 'Die Annalen von Darrowshire'? Das war mein Heim vor dem Krieg... mein Heim vor der Schlacht, die es zerstörte! Warum habt Ihr mir dieses Buch gebracht?\n\nAber seht doch nur hier! Am Ende sind Seiten, die Geschichten von den Tagen nach der Schlacht erzählen! Hier ist eine Passage über mich! Und eine über meinen Bruder Joseph! Ist dieses Buch echt?\n\nWir müssen die Wahrheit erfahren!" }, enUS = { progress = "You've come from the west?  How fare the rest of Lordaeron?  I know that Andorhal is lost, but has the Scourge yet reached fair Tirisfal?", completion = "What is this book?  The Annals of Darrowshire?  That was my home before the war... my home before the battle that destroyed it!  Why did you bring me this book?\n\nBut look here!  At the end there are pages that tell tales of the days beyond the battle!  Here is a passage about me!  And one about my brother Joseph!  Is this book true?\n\nWe must discover the truth!" } })
apply(5211, { "classic", "forever" }, { deDE = { progress = "Die armen Verteidiger von Darrowshire rufen in meinen Träumen nach mir, {name}. Ihr müsst sie befreien!", completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Mein Herz wird weniger weinen, da es weiß, dass zumindest einige der Verteidiger von Darrowshire nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind." }, enUS = { progress = "The poor defenders of Darrowshire cry out to me in my dreams, {name}.  You must free them!", completion = "It is good to hear you found the tortured souls of my brethren and freed them.  My heart will weep less, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge." } })
apply(5212, { "classic", "forever" }, { deDE = { progress = "Manche behaupten, dass ich mir zu viele Sorgen mache - ihnen sage ich: 'Ihr macht euch nicht genug Sorgen!'", completion = "Etwas hat sich in der chemischen Struktur der aktiven Wirkstoffe der Seuche verändert. Es sind mehr Daten erforderlich." }, enUS = { progress = "Some say I worry too much - to them I say, 'You don't worry enough!'", completion = "There is something that has changed in the chemical structure of the plague's active agents. More data is required." } })
apply(5213, { "classic", "forever" }, { deDE = { progress = "Wir stehen kurz davor herauszufinden, was dieser neue aktive Wirkstoff der Seuche sein kann!", completion = "Erstaunlich! Es wird Monate dauern, das zu sezieren und zu analysieren. Die Argentumdämmerung dankt Euch für Eure Bemühungen, {name}.\n\nMit unserem Segen, dürft ihr nun zwischen diesem Siegel der Dämmerung und dieser Rune der Dämmerung wählen. Ihr könnt diese Insignien anstelle einer Anstecknadel der Argentumdämmerung benutzen, um in unserem Namen Geißelsteine zu sammeln. Sprecht mich im Falle eines Verlusts einfach an und ich werde Euch einen Ersatz beschaffen." }, enUS = { progress = "We are on the verge of discovering what this new active plague agent may be!", completion = "Astonishing! This will take months to dissect and analyze. The Argent Dawn thanks you for your efforts, {name}.\n\nWith our blessing, take your pick between either this Seal of the Dawn or this Rune of the Dawn.  You can use either of them instead of a standard Argent Dawn Commission to collect scourgestones on our behalf.  Should you lose yours, speak with me and I'll get you a replacement." } })
apply(5215, { "classic", "forever" }, { deDE = { completion = "Möge die Macht des Lichts in diesen dunklen Zeiten auf Euch scheinen, {class}. Ich bin erfreut, als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel zu dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel sicherstellen, die es in den Westlichen Pestländern gibt.\n\nMacht Euch bereit, oh Held, ein glorreicher Kampf gegen die niederträchtige Geißel steht Euch bevor!" }, enUS = { completion = "May the power of the Light shine upon you in these dark times, {class}.  I am pleased to serve as your coordinator for our plan to sabotage the Scourge's cauldrons.\n\nOur goal will be to change the composition of the plague that the cauldrons create into something that negatively affects the Scourge.  In order to affect this change, you will need to secure access to each of the four cauldrons present in the Western Plaguelands.\n\nStand ready hero, for a glorious battle against the vile Scourge awaits you!" } })
apply(5216, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The key taken from Cauldron Lord Bilemaw is a perfect fit in unlocking the access panel.  A foul stench emanates from the opened panel as an unknown mix of concentrated substances swirl inside the cauldron.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point." } })
apply(5217, { "classic", "forever" }, { deDE = { progress = "Willkommen in der relativen Sicherheit der Chillwindspitze, {name}. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht {name}... Alchimist Arbington sollte in der Lage zu sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil über die Geißel haben, wenn die Zeit für den Kampf gekommen ist!" }, enUS = { progress = "Welcome back to the relative safety of Chillwind Camp, {name}.  What progress on the cauldrons do you have to report?", completion = "Well done {name} - it should take Alchemist Arbington no time at all to analyze this and devise a counter agent to introduce into the cauldron.  If we are able to pump out enough of it into the air, we might be able to weaken all the Scourge present here.\n\nThis will no doubt be an ongoing ordeal; we will need to continually hit these cauldrons and introduce our reagents into their mix.  Still, if we can keep it up, we will have a huge advantage over Scourge when the time comes for battle!" } })
apply(5219, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der makabre Schlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The macabre key found on the cauldron lord easily slides into a keyhole and then disappears, allowing you permanent access to it.  Crude, viscous ichors pulsate through twisted tubes within the cauldrons underpinnings.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point." } })
apply(5220, { "classic", "forever" }, { deDE = { progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, {name}!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Alchimist Arbington dürfte weitere Informationen darüber haben, also sprecht so bald wie möglich mit ihm." }, enUS = { progress = "We know that each cauldron employs a different mix of reagents to generate its plague-inducing toxin; likewise, we know that we will need to develop a counter agent that is unique for each cauldron.  Your sample from Dalson's Tears will be the key to figure out that cauldron's distinct reagent requirement.", completion = "Ah, there is plenty in here for study.  Well done, {name}!\n\nFor now, the next step is in our hands.  We'll need to produce a list of reagents that, when combined with what is already in the cauldron, will act as its counter.\n\nThe only way we will be able to introduce this is by placing the reagents into the cauldron directly.  Alchemist Arbington will have more information on that, so be sure to speak with him at your earliest convenience." } })
apply(5222, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen beiden Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The cauldron lord's key unlocks the access panel to this cauldron and then disappears, much like the other keys have for the previous two cauldrons you've dealt of.  A putrid smelling substance churns violently beneath the platform of the cauldron.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point." } })
apply(5223, { "classic", "forever" }, { deDE = { progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, {name}! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nAlchimist Arbington wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!" }, enUS = { progress = "Once we successfully analyze the sample drawn from the Writhing Haunt's cauldron, it will provide us with a third avenue to deliver a devastating counter agent onto the Scourge!", completion = "Another finely executed mission, {name}!  This makes three cauldrons available to us to turn against the Scourge.  If Kel'Thuzad's necromantic dominance over these lands wasn't as strong as it currently is, I'd dare say you'd shut them down completely!\n\nAlchemist Arbington will have a report on what this cauldron - as well as the other cauldrons subverted - will require to deliver our counter agent to the plague.  With that, the time has come to bring the last cauldron of the west under our influence!" } })
apply(5225, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for High Priestess MacDonnell back at Chillwind Point." } })
apply(5226, { "classic", "forever" }, { deDE = { progress = "Gahrrons Trauerfeld beherbergt den letzten Kessel hier im Westen, zu dem wir Zugang brauchen. Wenn wir eine Probe der Seuche haben, die er ausspeit, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt den letzten Kessel für uns entriegelt! Alchimist Arbington wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Kommandant Valorfist Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Danke, oh Held!" }, enUS = { progress = "Gahrron's Withering houses the last cauldron here in the west that we need access to.  Once we have a sample of the plague it spews forth, we will be able to introduce our reagents into the environment through four separate vessels!  The Scourge will be hard pressed to keep us out of all four, even with the power of Kel'Thuzad behind them.", completion = "Congratulations {name}, you've unlocked the last cauldron for us!  Alchemist Arbington will soon know what this cauldron requires as far as reagents needed for the mix.\n\nAs for you, I am sure that Commander Valorfist will want to thank you personally for the assistance you've given us.  Without you, our struggle against the Scourge would have been nearly insurmountable.  Thank you, hero!" } })
apply(5228, { "classic", "forever" }, { deDE = { completion = "Aus den Schatten, Bruder {race}, entbiete ich meine Grüße. Ich werde als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel hier in den Westlichen Pestländern sicherstellen.\n\nDie Zeit ist gekommen, dass Ihr den Sturm gegen die Geißel anführt." }, enUS = { completion = "From the shadows, brother {race}, I bid you greetings.  I am to serve as your coordinator for our plan to sabotage the Scourge's cauldrons.\n\nOur goal will be to change the composition of the plague that the cauldrons create into something that negatively affects the Scourge.  In order to affect this change, you will need to secure access to each of the four cauldrons here in the Western Plaguelands.\n\nThe time has come for you to lead the charge against the Scourge, hero." } })
apply(5229, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe, verschwindet aber, nachdem Ihr ihn benutzt habt. Ihr habt aber so ein Gefühl, dass Ihr den Zugang jetzt auch ohne einen Schlüssel öffnen könnt. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The key taken from Cauldron Lord Bilemaw is a perfect fit in unlocking the access panel, though it disappears after you use it.  Still, you think you can open the panel now without a key.  A foul stench emanates from the opened panel as an unknown mix of concentrated substances swirl inside the cauldron.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Shadow Priestess Vandis back at the Bulwark." } })
apply(5230, { "classic", "forever" }, { deDE = { progress = "Willkommen in der relativen Sicherheit des Bollwerks, {name}. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht {name} - Apotheker Dithers sollte in der Lage sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil gegenüber der Geißel haben, wenn die Zeit für den Kampf gekommen ist!" }, enUS = { progress = "Welcome back to the relative safety of the Bulwark, {name}.  What progress on the cauldrons do you have to report?", completion = "Well done {name} - it should take Apothecary Dithers no time at all to analyze this and devise a counter agent to introduce into the cauldron.  If we are able to pump out enough of it into the air, we might be able to weaken all the Scourge present here.\n\nThis will no doubt be an ongoing ordeal; we will need to continually hit these cauldrons and introduce our reagents into their mix.  Still, if we can keep it up, we will have a huge advantage over Scourge when the time comes for battle!" } })
apply(5231, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Skelettschlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The skeletal key found on the cauldron lord easily slides into a keyhole and then disappears, allowing you permanent access to it.  Crude, viscous ichors pulsate through twisted tubes within the cauldrons underpinnings.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Shadow Priestess Vandis back at the Bulwark." } })
apply(5232, { "classic", "forever" }, { deDE = { progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, {name}!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Apotheker Dithers dürfte weitere Informationen darüber haben, also sprecht mit ihm, sobald es Euch beliebt." }, enUS = { progress = "We know that each cauldron employs a different mix of reagents to generate its plague-inducing toxin; likewise, we know that we will need to develop a counter agent that is unique for each cauldron.  Your sample from Dalson's Tears will be the key to figure out that cauldron's distinct reagent requirement.", completion = "Ah, there is plenty in here for study.  Well done, {name}!\n\nFor now, the next step is in our hands.  We'll need to produce a list of reagents that, when combined with what is already in the cauldron, will act as its counter.\n\nThe only way we will be able to introduce this is by placing the reagents into the cauldron directly.  Apothecary Dithers will have more information on that, so be sure to speak with him as soon as possible." } })
apply(5233, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "The cauldron lord's key unlocks the access panel to this cauldron and then disappears, much like the other keys have for the previous ones you've dealt of.  A putrid smelling substance churns violently beneath the platform of the cauldron.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Shadow Priestess Vandis back at the Bulwark." } })
apply(5234, { "classic", "forever" }, { deDE = { progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, {name}! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nApotheker Dithers wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!" }, enUS = { progress = "Once we successfully analyze the sample drawn from the Writhing Haunt's cauldron, it will provide us with a third avenue to deliver a devastating counter agent against the Scourge!", completion = "Another finely executed mission, {name}!  This makes three cauldrons available to us to turn against the Scourge.  If Kel'Thuzad's necromantic dominance over these lands wasn't as strong as it currently is, I'd dare say you'd shut them down completely!\n\nApothecary Dithers will have a report on what this cauldron - as well as the other cauldrons subverted - will require to deliver our counter agent to the plague.  With that, the time has come to bring the last cauldron of the west under our influence!" } })
apply(5235, { "classic", "forever" }, { deDE = { progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt." }, enUS = { progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Shadow Priestess Vandis back at the Bulwark." } })
apply(5236, { "classic", "forever" }, { deDE = { progress = "Gahrrons Tränenfeld beherbergt den letzten Kessel, zu dem wir hier im Westen Zugang brauchen. Wenn wir eine Probe der Seuche von diesem Kessel haben, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt den letzten Kessel für uns entriegelt! Apotheker Dithers wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Hochexekutor Derrington Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Ich danke Euch, {class}." }, enUS = { progress = "Gahrron's Withering houses the last cauldron that we need to acquire access to here in the west.  Once we have a sample of the plague from that cauldron, we will be able to introduce our reagents into the environment through four separate vessels!  The Scourge will be hard pressed to keep us out of all four, even with the power of Kel'Thuzad behind them.", completion = "Congratulations {name}, you've unlocked the last cauldron for us!  Apothecary Dithers will soon know what this cauldron requires as far as reagents needed for the mix.\n\nAs for you, I am sure that High Executor Derrington will want to thank you personally for the assistance you've given us.  Without you, our struggle against the Scourge would have been nearly insurmountable.  I thank you, mighty {class}." } })
apply(5241, { "classic", "forever" }, { deDE = { completion = "Ihr habt Pamela gesehen? Sie lebt?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist nur immer noch in dieser Welt... Warum bist du umgekommen, während das Schicksal mich am Leben erhält? Ich würde sofort mit dir tauschen und durch das tote Darrowshire wandern, als Geisterscheinung und allein!\n\nAch, aber diese Neuigkeiten können das Schicksal nicht ändern. Ich danke Euch, {name}. Jetzt brennt meine Pflicht, meine Pflicht zur Rache, so heiß wie noch nie." }, enUS = { completion = "You've seen Pamela?  She's alive?\n\nShe's dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world.  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!\n\nAh, but this news cannot change fate.  Thank you, {name}.  Now my duty, my duty to revenge, burns hot as ever." } })
apply(5242, { "classic", "forever" }, { deDE = { progress = "Ohne Fel'dan werden die Mitglieder des Schattenrates hoffentlich ihr Ziel aus den Augen verlieren und untereinander zu streiten beginnen. Sie werden um die Macht kämpfen und Reichtümer für zukünftige Pläne anhäufen. Das wird eine günstige Zeit sein, um sie und ihre Dämonensklaven zu vernichten.", completion = "Gelobt sei die Erdenmutter, {name}! Danke! Das ist wirklich ein großer Tag!\n\nDer Schattenrat wird es nach diesem Schlag gegen seine Hierarchie schwer haben, wieder in demselben Maße Macht zu erlangen wie zuvor. Heute habt Ihr etwas Großes geleistet!" }, enUS = { progress = "Without Fel'dan, the Shadow Council will hopefully lose focus and start infighting. They will struggle with one another for control and hoard assets for future plans. That will be an opportune time to devastate them and their demon slaves.", completion = "Earthmother be praised, {name}! Thank you! This is a great day, indeed!\n\nThe Shadow Council will be hard pressed to scale to the same levels of power they once held with this blow to their hierarchy. You have done a great thing this day!" } })
apply(5243, { "classic", "forever" }, { deDE = { progress = "Seid vorsichtig, vermutlich haben nicht alle Vorratskisten die Zerstörung der Stadt überstanden. Die Geißel wagt es zwar nicht, das Wasser zu berühren, aber das heilige Wasser wird sicherlich keine Verseuchung durch Gezücht verhindern.", completion = "Gut gemacht, {race}. Ihr habt bewiesen, dass Ihr, auch wenn Ihr anderen gegenüber tolerant seid, vor nichts Halt machen werdet, um die Diener von Kel'Thuzad zu vernichten." }, enUS = { progress = "Be wary, not all supply crates will have survived the destruction of the city. The Scourge dare not touch the water but surely the holy water will not prevent vermin infestations.", completion = "Well done, {race}. You have proven that while you are tolerant of others, you will stop at nothing to destroy the minions of Kel'Thuzad." } })
apply(5244, { "classic", "forever" }, { deDE = { completion = "Nun ja, sicher, ich kann Euch mehr über Kel'Theril berichten. Wohlgemerkt, ich bin kein Historiker, aber ich kann Euch erzählen, was ich dort sah..." }, enUS = { completion = "Well, sure, I can tell you more about Kel'Theril. Mind you now, I'm no historian, but I can tell ya about what I saw there..." } })
apply(5245, { "classic", "forever" }, { deDE = { progress = "Warum kommt Ihr hierher?", completion = "Über die Vergangenheit der Hochelfen möchte ich nicht gern sprechen, {name}. Bitte, es schmerzt mich, an all das zu denken, was geschehen ist... Und es gibt keine Möglichkeit, die Dinge wieder in Ordnung zu bringen." }, enUS = { progress = "Why have you come here?", completion = "The past of the high elves is something that I do not wish to discuss, {name}. Please, it pains me to think of all that has happened... And that there is no way to make things right." } })
apply(5246, { "classic", "forever" }, { deDE = { progress = "Nur mit Hilfe der Seiten der hochheiligen Schriften kann ich erkennen, ob ich Euch helfen kann oder nicht...", completion = "Die Seiten wurden seit vielen, vielen Jahren nicht mehr berührt..." }, enUS = { progress = "It is only in the pages of the sacred writings that I will be able to discern whether or not I can help you...", completion = "The pages have gone untouched for many many years..." } })
apply(5247, { "classic", "forever" }, { deDE = { progress = "Das Relikt muss in die Hände der absolut Vertrauenswürdigsten gelegt werden. Es darf nicht wieder gestohlen werden...", completion = "Mit diesen Elementen kann ich die Fragmente zusammenfügen... hoffentlich zu dem, was sie einst waren." }, enUS = { progress = "The relic must be placed in the hands of only the most trustworthy. It can not be stolen again...", completion = "Using these elements, I can fuse the fragments together... to hopefully what they once were." } })
apply(5248, { "classic", "forever" }, { deDE = { progress = "Verrrrrrflucht... Fürrrr immmmerrrr...", completion = "Bitteeeeee, lasssssst miiiiiiiiich..." }, enUS = { progress = "Currrrrsed... Forevvvverrrr...", completion = "Pleeease, leeeave meeeeee..." } })
apply(5249, { "classic", "forever" }, { deDE = { completion = "Ein Freund von Ivy Leafrunner? Ich freue mich, Euch kennen zu lernen, {name}." }, enUS = { completion = "A friend of Ivy Leafrunner? Nice to meet you, {name}." } })
apply(5250, { "classic", "forever" }, { deDE = { completion = "Ein Schüler von Daryn Lightwind? Ich freue mich, Euch kennen zu lernen, {name}." }, enUS = { completion = "A student of Daryn Lightwind? Nice to meet you, {name}." } })
apply(5251, { "classic", "forever" }, { deDE = { completion = "Phantastisch, {name}! Über Jahre hinweg gesammelte Informationen, verloren! Der Scharlachrote Kreuzzug wird diesen Schlag in den folgenden Wochen sicherlich spüren." }, enUS = { completion = "Outstanding, {name}! Years of intelligence, lost! The Scarlet Crusade will surely feel this blow in the coming weeks." } })
apply(5252, { "classic", "forever" }, { deDE = { progress = "Es ist eine Weile her, seit Ihr weggegangen seid, {name}. Wie ist es Euch ergangen?", completion = "Ist das... für was ich es halte?" }, enUS = { progress = "It has been some time since you left, {name}. How have you fared?", completion = "Is that... what I think it is?" } })
apply(5253, { "classic", "forever" }, { deDE = { progress = "Ja, {race}?", completion = "Ich habe von dem Kristall von Zin-Malor gehört; der Benutzer des Kristalls wird unglaublicher arkaner Macht fähig, aber nur, wenn er wirklich würdig ist. Ich bin beeindruckt, dass Ihr nicht nur den Kristall wiederbeschafft habt, sondern auch Eure eigenen Grenzen erkannt und nicht versucht habt, den Kristall selbst zu benutzen.\n\nDanke, dass Ihr ihn mir gebracht habt, {name}. Wir werden ihn sicher aufbewahren, und mögen die verfluchten Geister, die den zerbrochenen Kristall einst bewachten, endlich ihren Frieden finden." }, enUS = { progress = "Yes, {race}?", completion = "I have heard of the Crystal of Zin-Malor; the user of the crystal becomes capable of incredible arcane power, but only if truly worthy. I am impressed that you not only recovered the crystal, but you also realize your own limits, and did not attempt to use the crystal yourself.\n\nThank you for bringing it to me, {name}. We will keep it safe, and may the cursed sprits that once guarded the shattered crystal finally be at peace." } })
apply(5261, { "classic", "forever" }, { deDE = { completion = "Das ist wahr. Ich suche nach jemandem, der für mich Wölfe jagt! Seid Ihr diese Person?" }, enUS = { completion = "That's true.  I'm looking for someone to hunt me some wolves!  Are you that person?" } })
apply(5262, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da, {name}?", completion = "Was bedeutet das für den Kreuzzug? Könnte es wirklich sein, dass seine Mitglieder sich unter der Kontrolle dieses Dämons befanden? Und unwissentlich als Bauern für ein größeres Übel dienten?" }, enUS = { progress = "What have you got there, {name}?", completion = "What will this mean to the Crusade? Could it be possible that they have been under the control of this demon? Unwittingly serving as the pawns to a greater evil?" } })
apply(5263, { "classic", "forever" }, { deDE = { progress = "Der Baron hat mehr Menschen getötet, als Ihr wahrscheinlich in Eurem Leben gesehen habt.", completion = "Es ist viele Jahre her, dass ich einen Helden in unsere Ränge eingeführt habe. Ihr seid der Erste, dem seit Jahren eine Audienz bei Lord Maxwell gewährt wird." }, enUS = { progress = "The Baron has slain more people than you have most likely seen in your lifetime.", completion = "It has been many years since I have ushered a champion into our ranks. You are the first to be granted audience with Lord Maxwell in years." } })
apply(5264, { "classic", "forever" }, { deDE = { completion = "Ihr seid ein würdiger Verbündeter, {name}. Ihr sollt die Belohnung für Eure standhafte Hingabe ernten." }, enUS = { completion = "You are a worthy ally, {name}. You shall reap the rewards of your stalwart dedication." } })
apply(5265, { "classic", "forever" }, { deDE = { completion = "Boah..." }, enUS = { completion = "Whoa..." } })
apply(5281, { "classic", "forever" }, { deDE = { completion = "Alen hat also endlich jemanden gefunden, der mutig genug ist, hmm?" }, enUS = { completion = "Alen has finally found someone brave enough, eh?" } })
apply(5282, { "classic", "forever" }, { deDE = { completion = "<Egan wischt eine Träne weg.>\n\nHabt Ihr meine Mutter gesehen, {name}? Habt Ihr sie befreit?\n\nIhr seid ein leuchtendes Beispiel des Anstands." }, enUS = { completion = "<Egan wipes a tear from his eye.>\n\nDid you see my mother, {name}? Did you free her?\n\nYou are a shining example of decency. For your troubles..." } })
apply(5283, { "classic", "forever" }, { deDE = { progress = "Ah, es geht nichts über eine gute Schmiedebräune. Am Schürzenstreifen kann man erkennen, wer 'ne wirklich gute Bräune hat.", completion = "So, {name}. Danach gibt es keinen Weg zurück. Es ist noch nicht zu spät, Spielzeugmacher, äh, Waffenschmied zu werden.\n\nIch denke, dass Ihr die richtige Entscheidung trefft." }, enUS = { progress = "Ah, ain't nothing like a good forge tan. Ye can tell who's got the really good tans by their apron lines.", completion = "This be it, {name}. After this, there ain't no way to turn back. It's not too late to become a toy maker, er, weaponsmith.\n\nI trust ye'll make the right decision." } })
apply(5302, { "classic", "forever" }, { deDE = { progress = "Für den Ruhm der Horde!", completion = "Dies ist der letzte Schritt, bevor Ihr Eure neue Karriere als Waffenschmied beginnen könnt, {name}. Solltet Ihr Euch dazu entscheiden abzuspringen, ist jetzt Eure letzte Gelegenheit dazu. Anderenfalls bereitet Euch darauf vor, vom Wissen verzehrt zu werden!" }, enUS = { progress = "For the glory of the Horde!", completion = "This is the final step before you begin your new career as a weaponsmith, {name}. Should you choose to back out, now would be your last chance. Otherwise, prepare to be consumed by knowledge!" } })
apply(5306, { "classic", "forever" }, { deDE = { progress = "Die Legende besagt, dass Vosh'gajins Schlangenstein eine Axt mit einer einzigen Anwendung 1000 Jahre lang messerscharf machen würde!", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Axtschmied werden? Denkt daran, die Türen zu Schwertschmied und Hammerschmied werden Euch dann für immer verschlossen sein." }, enUS = { progress = "Legend states that one use of Vosh'gajin's snakestone will keep an axe razor sharp for a 1000 years!", completion = "So you are certain this is what you want? To become an axesmith? Remember, the doors to becoming a swordsmith and hammersmith will close forever." } })
apply(5307, { "classic", "forever" }, { deDE = { progress = "Habt Ihr vergessen, welche Aufgabe Euch aufgetragen wurde, {name}?", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Schwertschmied werden? Denkt daran, die Türen zu Hammerschmied und Axtschmied werden Euch dann für immer verschlossen sein." }, enUS = { progress = "Have you forgotten what it is that you were tasked with, {name}?", completion = "So you are certain that this is what you want? To become a swordsmith? Remember, the doors to becoming a hammersmith and axesmith will close forever." } })
apply(5321, { "classic", "forever" }, { deDE = { progress = "Ist Kerlonian angekommen?", completion = "Oh, ich bin ja so froh, dass Kerlonian es geschafft hat! Und ich bin sicher, dass ich ihn hier irgendwo süß und fest schlafend antreffen werde, nicht wahr?\n\nDanke, dass Ihr ihm den Weg gezeigt habt, {name}." }, enUS = { progress = "Has Kerlonian arrived?", completion = "Oh, I am so happy Kerlonian made it! And I'm sure I'll find him sleeping somewhere around here, won't I?\n\nThank you for showing him the way, {name}." } })
apply(5341, { "classic", "forever" }, { deDE = { progress = "Neigt Euer Haupt in meiner Anwesenheit, {race}. Schließlich gehöre ich zum Adel und Ihr seid ein dummer Bauerntölpel.", completion = "Gut gemacht, {race}. Jetzt muss ich mir mein Erbe sichern..." }, enUS = { progress = "Bow your head in my presence, {race}. I am a noble, after all, and you are a copperless peasant.", completion = "Excellent work, {race}. Now to secure my inheritance..." } })
apply(5342, { "classic", "forever" }, { deDE = { progress = "Sichert mir mein Vermögen und Ihr erhaltet einen Anteil an der Beute.", completion = "Großartig! Jetzt habe ich allein die Macht und das Vermögen des Hauses Barov!\n\n<Alexi wirft Euch einen großen Beutel zu.>\n\nUnd behaltet den Rest, dreckiges Tier!" }, enUS = { progress = "Secure my fortune and share in the spoils.", completion = "Wonderful! Now only I hold the power and fortune of house Barov!\n\n<Alexi throws a large bag at you.>\n\nAnd keep the change, you filthy animal." } })
apply(5343, { "classic", "forever" }, { deDE = { progress = "Sichert mir meine Zukunft und ich werde die Eure sichern.", completion = "Es gibt nur noch eine weitere Aufgabe, die Ihr für mich erledigen müsst, {name}." }, enUS = { progress = "Ensure my future and I shall ensure yours.", completion = "There is but one more task that I must ask of you, {name}." } })
apply(5344, { "classic", "forever" }, { deDE = { progress = "Ihr wollt Eure Bezahlung, was?", completion = "Das ist ein glorreicher Tag! Endlich wurde der Schandfleck des Hauses Barov eliminiert und mein Vermögen gesichert!\n\nNehmt dies und geht mir aus den Augen... Wurm." }, enUS = { progress = "You do want payment, do you not?", completion = "A glorious day it is! Finally, the pockmark of house Barov eliminated and my fortune secure!\n\nTake this and leave my sight, peasant." } })
apply(5361, { "classic", "forever" }, { deDE = { progress = "Welche Neuigkeiten habt Ihr, {class}? Ah - eine Nachricht von meinem Bruder, sagt Ihr? Nun dann, gebt den Bericht her!", completion = "Ich weiß nicht, in welcher Beziehung Ihr zu meinem Bruder steht, aber es sieht so aus, als würde er Euch vertrauen, {class}.\n\nIch bin Nataka Longhorn und möchte Euch im Geistwandlerposten willkommen heißen. Wir können Leute wie Euch hier gut brauchen, {class}! Sprecht mit anderen, vielleicht braucht man hier Eure Hilfe." }, enUS = { progress = "What news have you, {class}!  Ah - a message from my brother you say?  Well then, hand over the report!", completion = "I know not what connection you have with my brother but it would seem he has trust with you, {class}.\n\nI am Nataka Longhorn and would like to welcome you to Ghost Walker Post, we have many needs of a {class}! Talk with others, perhaps there is need of you here." } })
apply(5381, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr den Dämonenkasten?", completion = "Ah, der Dämonenkasten. Gebt ihn mir, {class}, und ich werde ihn öffnen... und Euch damit die Hand von Iruxos offenbaren." }, enUS = { progress = "{name}, do you have the Demon Box?", completion = "Ah, the Demon Box. Give it to me, {class}, and I shall open... and thus reveal to you the Hand of Iruxos." } })
apply(5382, { "classic", "forever" }, { deDE = { progress = "Der Schlächter muss aufgehalten werden!", completion = "Ich fühle, wie mein Geist heilt, {name}. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen, aber ich bin sicher, dass es noch mehr zu tun gibt." }, enUS = { progress = "The Butcher must be stopped!", completion = "I can feel my spirit healing, {name}. You have done my husband and I a great service, but I am certain there is more to be done." } })
apply(5384, { "classic", "forever" }, { deDE = { progress = "Seid vorsichtig, Kirtonos ist ein erfahrener Kämpfer.", completion = "Mit dem Tod von Kirtonos wird ein Kapitel in der schrecklichen Geschichte der Scholomance geschlossen. Aber es gibt noch mehr zu tun. Andere hier sind sich jetzt Eurer mutigen Taten bewusst. Nehmt das, {name}. Es ist ein Stück unserer eigenen Essenz. Sie ermöglicht Euch, mit den anderen verlorenen Seelen von Caer Darrow zu kommunizieren." }, enUS = { progress = "Be wary, Kirtonos is a seasoned fighter.", completion = "With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. There is, however, more to be done. Others here are now aware of your brave acts. Take this, {name}. It is a piece of our own essence. It will allow you to communicate with the other lost souls of Caer Darrow." } })
apply(5385, { "classic", "forever" }, { deDE = { progress = "Wie lief es in Jaedenar, {name}?", completion = "Ihr habt es geschafft! Gelobt sei Elune und welche Mächte auch immer Ihr anbetet, {name}. Ihr habt heute etwas Ehrenwertes und Großmütiges getan. Ich bin sicher, dass Arko'narin erfreut sein wird, dass Ihr Euch nicht nur die Zeit genommen habt, sie zu retten, sondern auch die Kreatur zu erledigen, die einen ihrer besten Freunde gefoltert hat.\n\nIch wünschte, ich könnte mehr für Euch tun, aber bitte, nehmt dies." }, enUS = { progress = "How did things go in Jaedenar, {name}?", completion = "You've done it! Praise be to Elune and whichever powers you worship, {name}. You have done an honorable and noble thing this day. I am certain Arko'narin will be pleased that you not only took the time to save her, but to also slay the creature who tortured one of her best friends.\n\nI wish I could do more for you, but please, take this." } })
apply(5386, { "classic", "forever" }, { deDE = { progress = "Mein Huf prickelt und mir läuft das Wasser im Mund zusammen, wenn ich an gebratenen Blutbauchfisch denke... Habt Ihr welchen dabei?", completion = "Ihr seid ein Retter, {name}! Diese Blutbauchfische sehen fast gut genug aus, um sie roh zu essen.\n\n\n\nHier, bitteschön. Wählt einen dieser Gegenstände als Bezahlung für diese Fische aus." }, enUS = { progress = "My hoof tingles and my mouth starts to water when I think of fried Bloodbelly fish... You have any on you?", completion = "You are a savior, {name}! These Bloodbelly fish look almost good enough to eat raw.\n\n\n\nHere you go - choose one of these items as a payment for these fish." } })
apply(5441, { "classic", "forever" }, { deDE = { progress = "Verdammter fauler B...\n\n Huch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!" }, enUS = { progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!" } })
apply(5461, { "classic", "forever" }, { deDE = { progress = "Ein Andenken der Erinnerung ist ein seltener Fund, {name}.", completion = "Ich hatte bezweifelt, dass solch ein Gegendstand existieren könnte. Das eröffnet uns definitiv eine unglaubliche Gelegenheit - eine, die wir nicht vergeuden dürfen.\n\nMacht Euch fertig, {name}, denn das, worum ich Euch bitten werde, wird Euch in die Tiefen der Hölle führen." }, enUS = { progress = "A keepsake of remembrance is a rare find, {name}.", completion = "I had doubted the possibility of such an item existing. This certainly opens up an incredible opportunity - one we must not squander.\n\nPrepare yourself, {name}, for what I am about to ask of you will take you into the depths of hell." } })
apply(5462, { "classic", "forever" }, { deDE = { progress = "Stellt keine Fragen, auf die Ihr keine Antworten wollt.", completion = "<Leonid sieht sich das Andenken an.>\n\nEuer Problem weckt Erinnerungen, von denen ich gehofft hatte, dass sie nie wieder an die Oberfläche kommen würden." }, enUS = { progress = "Do not ask questions of which you do not want answers.", completion = "<Leonid looks over the keepsake.>\n\nYour quandary stirs up memories that I had hoped would never resurface." } })
apply(5463, { "classic", "forever" }, { deDE = { progress = "Der Bereich um Menethils Geschenk herum ist außergewöhnlich kalt.", completion = "Ihr platziert das Andenken auf dem besudelten Boden." }, enUS = { progress = "The area around Menethil's Gift is exceptionally cold.", completion = "You place the keepsake on the tainted soil." } })
apply(5464, { "classic", "forever" }, { deDE = { progress = "<Leonid erschauert.>", completion = "Wie die Seele an dem Andenken hing, so soll sie an der physischen Gestalt von Ras Frostraunen hängen." }, enUS = { progress = "<Leonid shudders.>", completion = "As the soul clung to the keepsake, so shall it cling to the physical form of Ras Frostwhisper." } })
apply(5465, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Unmögliche getan?", completion = "Ich war sicher, dass Ihr mir als ein weiterer unglückseliger Geist Gesellschaft leisten würdet." }, enUS = { progress = "Have you done the impossible?", completion = "I was certain that you would be joining me as another hapless spirit." } })
apply(5466, { "classic", "forever" }, { deDE = { progress = "Ihr tragt die Bürde von Zehntausenden ruheloser Seelen, {name}.", completion = "Zehntausende Seele schreien wie eine auf, {name}! Ihr habt der Geißel und ihren Meistern einen tödlichen Schlag versetzt." }, enUS = { progress = "You carry the burden of ten thousand restless souls, {name}.", completion = "Ten thousand souls cry out in unison, {name}! You have struck a mortal blow to the Scourge and their masters." } })
apply(5481, { "classic", "forever" }, { deDE = { progress = "Wo ist diese nutzlose Monstrosität? Entweder habt Ihr, was ich benötige, oder Ihr verschwindet besser von hier und sucht es.", completion = "Was ist denn das? Düsterkraut?! Ich brauche kein Düsterkraut! Diese hirnlose Fleischmasse pflückt da draußen Gänseblümchen und bringt Gott weiß wie viele Tölpel wie Euch dazu, das Gleiche zu tun. Das sollte keine Beleidigung sein.\n\nNun denn, Ihr seid jetzt hier und das ist das einzig Wichtige. Da ich keine Zeit darauf verschwenden werde, dieser Monstrosität alles noch mal zu erklären, wie wäre es, wenn Ihr das sammelt, was ich wirklich benötige ... Verdammniskraut." }, enUS = { progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nVery well, you're here now and that's all that matters. Since I'm not going to bother to try to explain things to that abomination how about you collect what I really need... doom weed!" } })
apply(5482, { "classic", "forever" }, { deDE = { progress = "Hoffentlich ist das wichtig... Ich gehe davon aus, dass Ihr das benötigte Verdammniskraut habt?", completion = "Ah, mein Verdammniskraut. Exzellent!\n\n<Jungapotheker Holland reibt gierig seine Hände aneinander.>\n\nDas passt perfekt. Ihr habt mir, äh, der Fürstin heute einen großen Dienst erwiesen, {name}. Wie versprochen ist hier die Belohnung, die Ihr verdient." }, enUS = { progress = "This had better be good. I trust you have all of the doom weed that I require?", completion = "Ah, my doom weed. Excellent!\n\n<Junior Apothecary Holland rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, {name}. As promised here is the reward that you deserve." } })
apply(5501, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Knochen? Die Karawane wird jeden Moment hier sein. Ich benötige nur noch zehn weitere Kodoknochen, um den Gipfel meiner Karriere zu erreichen. Den Gipfel meiner Karriere, sage ich Euch!", completion = "Ah, prima! Meine Knochen!\n\nIch kann es kaum abwarten, dass die Jungs zuhause mein Gesicht auf dem Titel von Goblin'preneur sehen. Ich werde der reichste Goblin auf der Welt sein... und mein Sportlehrer hat immer gesagt, aus mir würde nie was werden." }, enUS = { progress = "Do you have the bones?  The caravan will be here any moment.  I need just ten more kodo bones to reach a career high.  A career high, I tell you!", completion = "Ah, goodie!  My bones!\n\nI can't wait till the chaps at home see my face on the front cover of Goblin'preneur.  I'll be the richest goblin in the world... and my physical education teacher said I would never amount to anything." } })
apply(5504, { "classic", "forever" }, { deDE = { progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!" }, enUS = { progress = "Ah, noble {class}!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, {name}.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!" } })
apply(5507, { "classic", "forever" }, { deDE = { progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!" }, enUS = { progress = "Ah, noble {class}!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, {name}.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!" } })
apply(5513, { "classic", "forever" }, { deDE = { progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!" }, enUS = { progress = "Ah, noble {class}!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, {name}.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!" } })
apply(5514, { "classic", "forever" }, { deDE = { progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Dithers hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Dithers sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Dithers sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zum Bollwerk gewesen." }, enUS = { progress = "Yeah, I know who you are, and I know why you're here.  Dithers sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Dithers said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Dithers imbue them already?  Excellent... otherwise, it would have been a long trip back to the Bulwark for you." } })
apply(5515, { "classic", "forever" }, { deDE = { progress = "<Eva verschwimmt immer wieder mal mehr, mal weniger.>", completion = "Die Tasche der Schrecken!" }, enUS = { progress = "<Eva fades in and out of focus.>", completion = "The bag of horrors!" } })
apply(5522, { "classic", "forever" }, { deDE = { progress = "Ihr seid also derjenige, der an der Blackrockspitze Böses im Schilde führt, ja? Habt Ihr, worum ich gebeten habe?", completion = "Ah, sehr gut. Ihr kennt die böse Macht nicht, für die Ihr gearbeitet habt, aber nun werdet Ihr die Wahrheit erfahren. Und fürchtet Euch nicht - ich bin kein Diener dieses Meisters. Ich bin Leonid Barthalomew, bekannt als 'der Geachtete' bei meinen Brüdern der Argentumdämmerung.\n\nIch habe Tinkee mit einer List dazu gebracht, Euch und die Dracheneier zu mir zu schicken. Und es ist gut, dass mein Trick erfolgreich war, denn wenn diese Eier das geplante Ziel erreicht hätten, wäre eine große Macht in die Hände des Feindes gefallen." }, enUS = { progress = "You are the one up to mischief in Blackrock Spire, yes?  Do you have what I asked for?", completion = "Ah, very good.  You do not know the evil power for whom you have labored, but now you will know the truth.  And fear not--I am no servant of that master.  I am Leonid Barthalomew, known as \"the Revered\" to my brethren in the Argent Dawn.\n\nI tricked Tinkee into sending you and the dragon eggs to me.  And it is good that my trick was successful, for had these eggs reached their intended destination, a great power would have fallen into the hands of the enemy." } })
apply(5526, { "classic", "forever" }, { deDE = { progress = "Mit dem versiegelten Reliquiar der Reinheit in unserem Besitz, wird es uns nicht nur möglich sein, eine verderbte Gefahr aus dieser Welt zu bannen. Stattdessen können wir sie sogar in Ruhe studieren. Vielleicht entdecken wir mit der Zeit neue Wege, um die Besudelung der Verderbnis zu bekämpfen, welche Azeroth seit jeher bedroht.\n\nIch bin sicher, dass Milli es so gewollt hätte...", completion = "Es ist vollbracht, {class}. Der Zirkel des Cenarius steht in Eurer Schuld. Der Krieg ist noch lange nicht zu Ende, doch mit Eurer Hilfe haben wir eine große Schlacht gegen die Mächte gewonnen, die uns die Verdammnis bringen wollen.\n\nBitte akzeptiert dies als Zeichen unserer ewigen Dankbarkeit. Wisset {name}, dass der Zirkel des Cenarius Euch für diese Tat als einen Helden willkommen heißt. Habt dank." }, enUS = { progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.\n\nI know Milli would have had it no other way...", completion = "It is done, brave {class}, and with that the Cenarion Circle is in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this as a token of our enduring gratitude.  Know that you are welcomed here as a hero of the Cenarion Circle for your great deed, {name}.  Thank you." } })
apply(5527, { "classic", "forever" }, { deDE = { progress = "Ein Requiliar der Reinheit ist schon für sich alleine ein Artefakt. Nur wenige wurden je hergestellt und von fast allen sagt man, dass sie im Laufe der Zeit verloren gingen.\n\n Ich muss gestehen, dass ich nun schon eine ganze Weile von dem Requiliar beim Südwindposten wusste. Ehrlich gesagt, mit den aufkommenden Unruhen in Silithus, dachte ich unser Geheimnis als das zu beIassen, was es ist - ein Geheimnis. Wenn zuviel bekannt würde, täte dies nur die Aufmerksamkeit des Feindes erregen.\n\nLeider ist die Zeit der Selbstgefälligkeit jetzt vorbei, insbesondere was die Situation in Eldre'Thalas angeht. Wir müssen handeln!", completion = "Ihr seid in der Tat so einfallsreich wie man sich erzählt. Der Zirkel des Cenarius ist gesegnet, Euch auf unserer Seite zu haben.\n\nMit dem Reliquiar in unseren Händen, empfinde ich das erste mal Erleichterung. Es fällt mir jetzt leichter darum zu bitten, dass Ihr Euch nicht nur einen bösartigen Dämonen gegenüber stellt, sondern Ihr sollt vielmehr noch, einen gefährlichen Gegenstand bergen..." }, enUS = { progress = "A Reliquary of Purity is an artifact unto itself.  Few were ever made, and almost all of them were thought to have been lost over time.\n\nI admit I have known about the one in Southwind for a little while now.  Honestly, with the rising turmoil in Silithus, I thought to keep our secrets just that - a secret.  To poke and prod would only cause suspicions of our enemies to rise.\n\nAlas, the time for complacency is at an end, especially with the situation in Eldre'Thalas.", completion = "Indeed, you are as resourceful as many claim.  The Cenarion Circle is blessed to have you working in our stead.\n\nWith the Reliquary once more in our hands, my mind is at ease.  I feel more comfortable asking you to not only face down a malfeasant demon, but also to bring back a dangerous item in the process..." } })
apply(5529, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}! Es wird lange dauern, bis sie ein weiteres Gelege von Großdrachen züchten können.\n\n... Zumindest hoffe ich das!" }, enUS = { completion = "Well done, {name}!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!" } })
apply(5531, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}! Ich habe gehört, Ihr seid mit einigen Dracheneiern hier? Na, dann lasst sie uns mal ansehen!", completion = "Da sind sie ja! Und in einem so hübschen Behälter. Die perfekte Größe!\n\nWir werden diese Eier an einem sicheren Ort aufbewahren, damit wir sie später untersuchen können, aber jetzt benötigen wir das Ding, in dem Ihr sie hergebracht habt.\n\nIch habe ein Gerät mit einer sehr speziellen Verwendung gebaut: Es dient dazu, die untoten Gelehrten von Scholomance zu vernichten. Sie studieren Großdrachen in ihren Bemühungen, einen verseuchten Drachenschwarm zu schaffen, und wir müssen ihre Fortschritte stoppen.\n\nIch nenne das Gerät Dämmerungstrickfalle, weil ... na ja, ich nicht sicher bin, ob es funktioniert!\n\nWürdet Ihr es für uns herausfinden?" }, enUS = { progress = "Hello, {name}!  I heard you were here with some dragon eggs?  Well, let's see them!", completion = "There they are!  And in such a nice container.  The perfect size!\n\nWe'll keep these eggs in a safe place so we can study them later, but right now we need that thing you brought them in.\n\nI have created a device with a very specific use: to destroy the undead scholars of the Scholomance.  They are studying dragons in their efforts to create a plagued dragonflight, and we must halt their progress.\n\nI call the device Dawn's Gambit, because... I'm not sure if it works!\n\nWill you find out for us?" } })
apply(5533, { "classic", "forever" }, { deDE = { completion = "Grüße, {class}. Ich habe einen Großteil meiner Studien der Scholomance gewidmet und glaube, dass ich eine Möglichkeit kenne, wie Ihr einen Schlüssel erlangen könnt, der Euch nach Belieben durch die Vordertür bringt.\n\nIch kann mir nur vorstellen, welch schreckliche Dinge im Inneren zu sehen sein werden, {name}. Ich weiß nicht, wie Ihr heroischen Typen das manchmal ertragt ..." }, enUS = { completion = "Well met, {class}.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire a key... one that will let you past the front door.\n\nI can only imagine what horrid sights are to be seen inside, {name}.  I don't know how you heroic types do it sometimes..." } })
apply(5534, { "classic", "forever" }, { deDE = { progress = "Also, {name}? Wo ist die Rune? Ihr seid doch ein guter Angestellter, nicht wahr? Ihr seid doch hier, um zu helfen?\n\nZwingt mich nicht, noch mal zu überdenken, ob ich Euch das zahle, was wir vereinbart haben. Was? Oh, wir haben gar nichts vereinbart? Na toll ... dann lasst Euch Zeit ... wisset nur, dass es wesentlich weniger sein wird, wenn Ihr lange braucht.", completion = "Haha! Großartig!\n\nIch werde bestimmt herausfinden, wofür das ist und warum Magus Rimtori - die Kuh, die mich angeheuert hat - es haben wollte. Ha! Jetzt habe ich Euch, ihr stinkenden Blutelfen! Kim'jael! Ha! Denen werde ich zeigen, wer hier die Ratten sind!\n\nDas war prima, {name}. Heißen Dank. Hier, nehmt diese Münze und verschwindet ... ich muss mich an die Arbeit machen." }, enUS = { progress = "Well, {name}? Where is the rune? You are a good employee, right? You're here to help?\n\nDon't make me think twice about paying you what we agreed upon. What? Oh, we didn't agree on anything? Oh, great... then take your time--just know that it'll be a lot less if you take a long time.", completion = "Haha! Wonderful!\n\nI'll be sure to find out what this is for and why Magus Rimtori--she's the cow that hired me--wanted it. Hah! I got you now, stinkin' Blood elves! Kim'jael! Ha! I'll teach them who the rats are!\n\nYa did good, {name}. Thanks a bundle. Here, take this coin and be off with ya--I've got some things to figure out." } })
apply(5535, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {class}. Danke für Eure Hilfe. Die Geister haben ihren Frieden und die Bedrohungen, die ihr Verlangen nach dem Arkanen angezogen hat, wurden dezimiert.\n\nIch bin sicher, dass beide Seiten des Konflikts, der Azeroth verheert, sehen werden, dass Ihr über solchen Dingen steht." }, enUS = { completion = "Well done, {class}. Thank you for your help. The spirits are at peace, and the threats that their desire for the arcane draw have been lessened.\n\nI am sure that both sides of the conflict that ravishes Azeroth will see you are above such things." } })
apply(5536, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Schlacht gegen die Satyrn, {class}?\n\nSind sie so stark, wie Ihr dachtet? Stärker? Oder vielleicht waren sie nichts angesichts Eurer eigenen Macht?", completion = "Gut gemacht, {class}. Ich sehe, dass Ihr nicht nur geschickt, sondern auch schlau seid. Solche Kreaturen zu besiegen ist ein Zeugnis Eurer Loyalität zu den Geschöpfen der Erdenmutter, auch wenn Ihr sie nicht als Eure Gottheit anerkennt. Man findet sie in allen Dingen auf diesem Planeten und darüber hinaus. Ihre Augen, eines dunkel und eines hell, ziehen über den Himmel und blicken immer auf uns herab.\n\nBitte, nehmt diesen kleinen Stapel Münzen als Wertschätzung dessen, was Ihr getan habt." }, enUS = { progress = "How goes your battle against the satyr, {class}?\n\nAre they as strong as you thought? Stronger? Or perhaps they were nothing to your own might.", completion = "Well done, {class}. I see you're not only skilled but cunning. To defeat such creatures is a testament to your loyalty to the tenants of the Earthmother, even if you do not recognize her as your own deity. She is in all things on this planet and beyond. Her eyes, one dark and one light, travel across the skies always gazing down upon us.\n\nPlease, take this small amount of coin in appreciation for what you have done." } })
apply(5537, { "classic", "forever" }, { deDE = { progress = "So morbid es vielleicht klingt, aber wir werden einen guten Vorrat geeigneter Skelettfragmente benötigen, um die äußere Schicht des Schlüssels herzustellen. Man nennt so etwas nicht umsonst Skelettschlüssel, wisst Ihr.", completion = "Das wird funktionieren, {name}! Jetzt bin ich dran... ich werde sie mit einem geeigneten Härter tränken, wodurch sie den starken Schmiedeprozess überstehen werden, den sie schließlich durchlaufen müssen.\n\nDer nächste Schritt wird sein, eine geeignete Form für den Schlüssel zu bekommen. Ich kenne einen Goblin-Schmied in Tanaris, der in der Vergangenheit Formen für ähnlich makabre Dinge hergestellt hat. Er arbeitet für den üblichen Auftraggeber der Goblins - den höchsten Bieter." }, enUS = { progress = "As morbid as it sounds, we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, {name}!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder." } })
apply(5538, { "classic", "forever" }, { deDE = { progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Arbington hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Arbington sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Arbington sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zur Chillwindspitze gewesen." }, enUS = { progress = "Yeah, I know who you are, and I know why you're here.  Arbington sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Arbington said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Arbington imbue them already?  Excellent... otherwise, it would have been a long trip back to Chillwind Point for you." } })
apply(5541, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr seid nicht wegen Munition hier, denn ich habe fast keine mehr!", completion = "Wunderbar, mehr Munition! Die Lieferung vom alten Loslor ist endlich da! Na ja, die Munition mag etwas verspätet ankommen, aber wie schon mein Großvater mir immer gesagt hat: Besser spät als nie!\n\nVielen herzlichen Dank, {name}. Ich habe bereits Käufer, die begierig auf dieses Zeug warten!" }, enUS = { progress = "I hope you're not here for ammo, because I'm almost out!", completion = "Great, more ammo!  Old Loslor's shipment finally came through!  The ammo might be late, but just like my grand daddy used to tell me: late's better than never!\n\nThank you much, {name}.  I already have buyers eager for this stuff!" } })
apply(5542, { "classic", "forever" }, { deDE = { progress = "Habt kein Mitleid mit den Dämonenhunden, {race}. Das sind Monstrositäten!", completion = "Gut gemacht, {name}. Kommt. Ruht Euch aus. Lasst uns essen und von längst vergangenen Tagen sprechen!" }, enUS = { progress = "Do not pity the demon dogs, {race}. They are abominations!", completion = "Well done, {name}. Come. Rest. Let us eat and talk of days long past!" } })
apply(5543, { "classic", "forever" }, { deDE = { completion = "Ihr seid ein leuchtendes Beispiel des Anstands, {race}! Es ist lange her, dass ich das Blut von Helden in meinen Adern gefühlt habe. Eure Taten der Tapferkeit sind wahrlich erhebend!" }, enUS = { completion = "You are a shining example of decency, {race}! It has been long since I have felt the blood of heroes pump through my veins. Your acts of bravery are uplifting!" } })
apply(5544, { "classic", "forever" }, { deDE = { progress = "Ihr werdet Euch an den Geschmack gewöhnen, {race}.", completion = "Möge das Licht über Euch wachen! Gesegnet seid Ihr." }, enUS = { progress = "You will grow to tolerate the taste, {race}.", completion = "May the Light watch over you! Bless you, young one." } })
apply(5545, { "classic", "forever" }, { deDE = { progress = "Der Termin kommt immer näher, {class}. Beeilt Euch bitte und holt diese Holzbündel.", completion = "Exzellent! Dank Euch sollte ich die Bestellung rechtzeitig zusammenstellen können. Um Euch meine Dankbarkeit zu zeigen, würde ich Euch gern ein paar Münzen als Entschädigung für Eure Mühen anbieten.\n\nVielen Dank und lebt wohl." }, enUS = { progress = "That deadline isn't getting any further away, {class}. Please hurry and collect those bundles of wood.", completion = "Excellent! Thanks to you, I should be able to complete the order in time. To show my gratitude, I would like to offer some coin as compensation for your troubles.\n\nThank you and farewell." } })
apply(5561, { "classic", "forever" }, { deDE = { progress = "Die Karawane wird bald hier sein; habt Ihr die fünf gezähmten Kodos, um die ich gebeten hatte?", completion = "<Smeed Scrabblescrew beginnt zu zählen.>\n\nDrei, vier und fünf... hervorragend, ich habe um fünf gezähmte Kodos gebeten und ich habe fünf gezähmte Kodos bekommen... Ich werde reich sein... ja, sehr reich. Ich würde zu gern den Ausdruck auf Bibblys grünem Gesicht sehen, wenn er von meinem Erfolg hört!" }, enUS = { progress = "The caravan will be here shortly; do you have the five new tamed kodos I was asking for?", completion = "<Smeed Scrabblescrew begins counting.>\n\nThree, four, and five... excellent, I ask for five tamed kodos and I get five tamed kodos... I am going to be rich... yes, very rich! I hope to see the look on Bibbly's green face when he hears about my success!" } })
apply(5581, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Dämonenportale in Mannorocs Koven verbannt?", completion = "Ich muss Euch loben, {name}. Eure Bemühungen haben beim Kampf gegen die dämonische Bedrohung sehr geholfen, und ganz Azeroth ist jetzt sicherer." }, enUS = { progress = "Have you banished the demon portals at Mannoroc Coven?", completion = "You are to be commended, {name}.  Your effort has helped greatly in fighting the demon threat, and all of Azeroth is safer because of it." } })
apply(5582, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr mir etwas zu zeigen?", completion = "Exzellent! Das wird für meine ständigen Studien der Machenschaften der Geißel unschätzbar sein. Vielen Dank, {name}, und falls Ihr noch mehr von diesen Schuppen findet, bringt sie mir bitte!" }, enUS = { progress = "{name}, do you have something to show me?", completion = "Excellent!  This will be invaluable in my continued studies of the machinations of the Scourge.  Thank you, {name}, and if you find more of these scales please bring them to me!" } })
apply(5601, { "classic", "forever" }, { deDE = { completion = "Wo ist meine Schwester Jessica? Sie ist vor langer Zeit fortgegangen, als ich noch ein kleines Mädchen war. Sie weinte so sehr, als sie fort ging. Ich weiß nicht, warum sie geweint hat! Vielleicht ist sie hingefallen und hat sich ihren Zeh gestoßen.\n\nAls Jessica hier war, haben wir immer gespielt und getanzt und hübsche Blumen rund um das Haus gepflückt. Und manchmal haben wir uns versteckt, wenn wir gesehen haben, dass Papa kam. Dann sind wir aus dem Versteck gekommen und haben ihn überrascht!\n\nKomm zurück, Jessica! Wenn du zurückkommst, dann kommt Papa vielleicht auch und wir können wieder zusammen spielen ..." }, enUS = { completion = "Where is my sister Jessica?  She left so long ago, when I was just a little girl.  She cried so much when she went away.  I don't know why she cried!  Maybe she fell and hit her toe.\n\nWhen Jessica was here we used to play games and dance and pick pretty flowers around the house.  And sometimes we'd hide when we saw daddy coming home, then jump out and surprise him!\n\nCome back, Jessica!  If you come back then maybe daddy will too and we can all play together again..." } })
apply(5621, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Sache gut gemacht und Elune gedient. Dafür danke ich Euch.\n\nBitte, nehmt diese Robe als ein Zeichen meiner Dankbarkeit. Sie bedeutet, dass Ihr Euch einen Platz in unserem Orden verdient habt. Wenn Ihr wollt, tragt sie mit Stolz, doch wie auch immer Ihr Euch entscheidet - wir werden Euch immer als einen der unsrigen anerkennen.\n\nGeht mit Elune, {name}, und danke." }, enUS = { completion = "You have done well and you have served Elune. For that, I thank you.\n\nPlease, take this robe as a token of my thanks. It signifies you have earned your place among our order. If you wish, wear it with pride, but either way, we will always recognize you as one of our own.\n\nGo with Elune, {name}, and thank you." } })
apply(5625, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Ihr tragt das Licht in Euch, so viel ist klar.\n\nHier, nehmt diese Robe. Sie dient als Zeichen Eurer Rolle innerhalb der Kirche und wird den Leuten dabei helfen, Euch als {class} zu erkennen - tragt sie, wann immer Ihr möchtet.\n\nIhr werdet Euch später weiteren Prüfungen unterziehen müssen. Tut, was Ihr könnt, um etwas über Eure Fähigkeiten und Eure Möglichkeiten zu erfahren. Versucht Euch einmal allein an ein oder zwei Kämpfen und dann mit anderen Reisenden zusammen.\n\nUnd keine Sorge ... in Euch steckt sehr viel Macht." }, enUS = { completion = "Well done, {name}. You got the Light inside you, that's for sure.\n\nHere, take this robe. It'll denote your role in the church and help people recognize you as a {class}--wear it if you want.\n\nLater, there will be more tests that you'll have to go through. Do what you can to learn about your abilities and what you're capable of. Try your hand at a fight or two alone, and then again with other travelers.\n\nBut don't fret none... you're as powerful as they come." } })
apply(5629, { "classic", "forever" }, { deDE = { completion = "Wunderbar, Ihr seid zurückgekehrt, {name}. Es erfreut Tyrande und mich immer, wenn diejenigen, die wir ausgebildet haben, in die Welt hinausziehen und sicher zu uns zurückkehren. Wie ist es Euch ergangen? Segnet Elune Eure Reisen immer noch? Vielleicht könnt Ihr mir mehr über Eure Reisen berichten, wenn wir über die Angelegenheiten gesprochen haben, die vor uns liegen." }, enUS = { completion = "Wonderful, you've returned, {name}. It always pleases Tyrande and myself when those we've trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels." } })
apply(5635, { "classic", "forever" }, { deDE = { completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern." }, enUS = { completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now." } })
apply(5637, { "classic", "forever" }, { deDE = { completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern." }, enUS = { completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now." } })
apply(5638, { "classic", "forever" }, { deDE = { completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber am wichtigsten ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern." }, enUS = { completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but most importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now." } })
apply(5639, { "classic", "forever" }, { deDE = { completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern." }, enUS = { completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now." } })
apply(5642, { "classic", "forever" }, { deDE = { completion = "Einer der wichtigsten Initiationsriten für einen {class} unseres Glaubens liegt vor uns, {name}. Ich werde Euch mehr erklären... Ihr seid dazu bereit." }, enUS = { completion = "One of the most important rites of passage for a {class} of our faith is upon us, {name}. I will explain more to you--you are ready." } })
apply(5644, { "classic", "forever" }, { deDE = { completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, {name}. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid." }, enUS = { completion = "Good, you've returned, and not a moment too late. We have great things to discuss, {name}. Your abilities are growing stronger, and we must make sure you are ready." } })
apply(5645, { "classic", "forever" }, { deDE = { completion = "Es ist schön, dass Ihr gekommen seid, {name}. Unser Volk ist stolz und stark und es wird Zeit, dass Ihr nicht nur lernt, selbst stolz und stark zu sein, sondern auch, solche Gefühle und Vertrauen in anderen zu wecken. Seid Ihr bereit, Bursche?" }, enUS = { completion = "It is good you've come, {name}. Our race is proud and strong, and it is time you learn to not only be so yourself, but to invoke such emotion and confidence in others. You prepared, lad?" } })
apply(5646, { "classic", "forever" }, { deDE = { completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, {name}. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid." }, enUS = { completion = "Good, you've returned, and not a moment too late. We have great things to discuss, {name}. Your abilities are growing stronger, and we must make sure you are ready." } })
apply(5648, { "classic", "forever" }, { deDE = { completion = "Gut, Kor'ja lebt also und zieht los, um unsere Stadt gegen diese bösartigen Menschen zu verteidigen. Ich wünsche mir oft, mich an die Schlachten vergangener Tage zurückzuerinnern; als Macht noch im Kampf gezeigt wurde und es oftmals der Weise war, der diejenigen vernichtete, die sich nur auf ihre Stärke verließen.\n\nIhr habt Eure Sache meiner Meinung nach gut gemacht, {name}. Nehmt jetzt diese Robe. Ob sie hilft oder ob sie Euch egal ist, Ihr habt sie Euch jedenfalls verdient, und ich bin stolz, Euch Bruder zu nennen." }, enUS = { completion = "Good, then Kor'ja lives and goes off to defend our town from those malicious humans. I often wish to remember days of battle; where power was shown in combat and it was the wise who often destroyed those who relied on just their strength.\n\nYou done good by me, {name}. You take this robe now. Maybe it help, maybe you not care, but you earned it and I'm proud to call you brother." } })
apply(5649, { "classic", "forever" }, { deDE = { completion = "Ahhh... Ihr seid also endlich zu Tai'jin gekommen. Das ist gut.\n\nIhr wisst bereits, dass wir nicht der gleiche Stamm sind, der sich einst der Horde angeschlossen hat. Wir sind jetzt viel stärker. Wir sind stärker, weil wir uns anpassen - das hat uns die Horde gelehrt. Wir besiegen unsere Feinde nicht mehr, um durch sie dann an Kraft zu gewinnen; jetzt gewinnen wir an Kraft und besiegen dann unsere Feinde.\n\nDer Unterschied mag fein sein, aber Ihr werdet es lernen. Ihr werdet es sehen. Der Stamm zählt auf Euch, dass Ihr solche Dinge lernt." }, enUS = { completion = "Ahh... so you finally come to Tai'jin. This be good.\n\nYou already know that we are not da same tribe that once joined with the Horde. We be much stronger now. We stronger 'cause we adapt--the Horde teach us that much. We no longer defeat our enemies and gain strength from them; now we gain strength, and then defeat our enemies.\n\nThe difference be subtle, but you will learn. You will see. The tribe count on you to learn such things." } })
apply(5650, { "classic", "forever" }, { deDE = { completion = "Ihr habt meine Prüfung mit Leichtigkeit bestanden. Gut.\n\nBald werdet Ihr bereit sein, mehr Verantwortung zu übernehmen, und dieser Weg wird Euch zu dunkleren Kräften führen... Kräfte, die kein {class} eines anderen Volkes besitzt.\n\nNehmt diese Robe als Symbol Eures Standes. Ihr habt sie Euch verdient. Wenn Ihr sie nicht tragen wollt, dann sei es so, Ihr könnt damit tun, was Ihr wollt. Ich und andere wie wir werden Euch immer Anerkennung dafür zollen, was Ihr in unseren Reihen erreicht habt." }, enUS = { completion = "You have passed my test with ease. Good.\n\nSoon, you will be ready to take on more responsibility and that road will lead to darker powers--powers that no {class} of another race has.\n\nTake this robe as a symbol of your station. You have earned it. If you do not wish to wear it, then so be it, you may do with it as you will. I and others like us will always acknowledge you for what you've achieved in our ranks." } })
apply(5651, { "classic", "forever" }, { deDE = { completion = "Endlich seid Ihr da. Euer Glaube allein wird Euch nicht helfen, die Aufgaben zu bewältigen, die vor Euch liegen. Etwas Dringlichkeit und ein wenig Ehrgeiz helfen auch." }, enUS = { completion = "Finally, you've arrived. Your faith alone will not allow you to pass the trials before you, young one. A sense of urgency and some ambition will help too." } })
apply(5654, { "classic", "forever" }, { deDE = { completion = "Ah, gut, da seid Ihr ja. Wir können Eure Ausbildung in den alten Wegen beginnen." }, enUS = { completion = "Ah, good, you be here now. We can start your training in the old ways." } })
apply(5660, { "classic", "forever" }, { deDE = { completion = "Ah, gut, ein Weiterer ist angekommen. Die Zeit mag für mich keine Rolle spielen, aber für Euch ist sie wichtig. Es gibt viel, das Ihr lernen müsst, und es gibt viel, das ich Euch beibringen möchte. Ihr müsst Euch einfach nur würdig erweisen. Tut dies, und Ihr werdet außerordentlich belohnt werden." }, enUS = { completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded." } })
apply(5662, { "classic", "forever" }, { deDE = { completion = "Ah, gut, ein Weiterer ist angekommen. Die Zeit mag für mich keine Rolle spielen, aber für Euch ist sie wichtig. Es gibt viel, das Ihr lernen müsst, und es gibt viel, das ich Euch beibringen möchte. Ihr müsst Euch einfach nur würdig erweisen. Tut dies, und Ihr werdet außerordentlich belohnt werden." }, enUS = { completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded." } })
apply(5673, { "classic", "forever" }, { deDE = { completion = "Elune segne Euch für Eure schnelle Rückkehr zu uns. Dies ist eine bedeutende Zeit für Eure Ausbildung und eine Zeit, die unser gesamter Orden sehr ernst nimmt. Wenn Ihr Euch von Eurer Reise hierher erholt habt, dann lasst es mich wissen. Wir können dann die Fortführung Eurer Ausbildung erörtern und die Frage, wohin Euch Euer Weg als Nächstes führen wird." }, enUS = { completion = "Elune bless you for returning so quickly to us. This is an important time in your training, and a time that all of our order take very seriously. When you've rested from your journey here, please, let me know. We can then discuss the continuation of your training and where your path will lead you next." } })
apply(5677, { "classic", "forever" }, { deDE = { completion = "Ah, der Zeitpunkt ist perfekt, {name}. Ich fragte mich langsam, ob meine Boten wohl erfolgreich waren. Es ist schön zu sehen, dass sie es waren, anderenfalls würde ich wetten, dass Ihr noch immer in der Welt umherzieht, um mehr über all die Bedrohungen zu lernen, denen sich unser Volk gegenübersieht.\n\nSeid Ihr bereit? Bereit für eine weitere Ausbildung, meine ich. Eure Macht wächst schnell und ich fühle, dass Ihr bereit seid, mehr über unseren Glauben zu lernen." }, enUS = { completion = "Ah, you have wonderful timing, {name}. I was beginning to wonder if all of my messengers had been successful. I'm glad to see they were, otherwise I would wager you'd still be out in the world learning more about all the threats that exist against our people.\n\nAre you ready? Ready for more training I mean. You're growing in power more quickly, and I feel you are ready to learn more about our faith." } })
apply(5713, { "classic", "forever" }, { deDE = { completion = "Ihr bringt sehr willkommene Neuigkeiten, {class}. Es ist gut zu hören, dass Aynasha lebt, und ich danke Euch dafür. Ich hoffe, dass Ihr eine Belohnung für Eure edlen Bemühungen annehmt. Möge Elune über Euch wachen und Euren Weg erleuchten." }, enUS = { completion = "You bring most welcome news {class}. It is good to hear that Aynasha is alive and well thanks to you. I would hope that you might accept a reward for your valor. May Elune watch over you and light your path." } })
apply(5721, { "classic", "forever" }, { deDE = { completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause käme! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!" }, enUS = { completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if came to our house, so I made some tea!\n\nI hope you like lots of sugar!" } })
apply(5722, { "classic", "forever" }, { deDE = { completion = "Der Körper scheint von Keulen oder Fäusten übelst zugerichtet worden zu sein, jedoch ist der Großteil der Kleidung und Ausrüstung offenbar noch vorhanden. Die Troggs scheren sich anscheinend nicht besonders um materielle Dinge.\n\nIhr beginnt, den Körper nach etwas Interessantem zu durchsuchen, das Magatha helfen könnte." }, enUS = { completion = "The body looks seriously beaten by clubs or fists, but most of the corpse's clothing and equipment still looks present. It seems the troggs do not overly care much for material wealth.\n\nYou begin to search the body for anything of interest that might help Magatha." } })
apply(5723, { "classic", "forever" }, { deDE = { completion = "Ich freue mich, dass Ihr Magathas Auftrag so ernst genommen habt. Ich danke Euch, {name}. Den Troggs wird es jetzt bestimmt schwerer fallen, an die Oberfläche zu gelangen, denn ihre Zahl wurde beträchtlich reduziert.\n\nVielleicht können wir uns in der Zukunft etwas Zeit nehmen und herausfinden, woher diese Kreaturen kamen und was sie eigentlich wollen." }, enUS = { completion = "I am glad to see you took Magatha's task seriously. Thank you, {name}. I'm sure the troggs will have a harder time coming to the surface with their numbers so greatly reduced.\n\nPerhaps in the future we can take time to figure out where such creatures came from, and what they really want." } })
apply(5724, { "classic", "forever" }, { deDE = { progress = "Habt Ihr irgendwas gefunden, {name}? Jeder Hinweis darauf, warum einer ihrer Klanangehörigen unnötig sterben musste, wäre hilfreich.", completion = "Ausgezeichnet, {name}. Danke.\n\nMagatha sagte mir, dass Ihr dies hier bekommen sollt, wenn Eure Suche nach ihrem Klanangehörigen erfolgreich war. Bitte, nehmt das als Dank." }, enUS = { progress = "Were you able to find anything, {name}? Any clues as to why one of her clansman had to die needlessly would be helpful.", completion = "Excellent, {name}. Thank you.\n\nMagatha told me that if you were successful in finding her clansman that you be given this. Please, take it in thanks." } })
apply(5725, { "classic", "forever" }, { deDE = { progress = "Ich muss mich noch um Hunderte anderer Dinge kümmern, {class}. Habt Ihr die Bücher?", completion = "Gut, {class}. Ihr habt der dunklen Fürstin gut gedient. Mit Eurer unablässigen Beharrlichkeit und Eurem Ehrgeiz habt Ihr viel für die Untertanen der Fürstin geleistet. Besucht mich irgendwann einmal wieder. Vielleicht habe ich dann ja neue Aufgaben für Euch, die der dunklen Fürstin bei ihren Versuchen, den Lichkönig zu stürzen und die Geißel endgültig zu befreien, helfen könnten." }, enUS = { progress = "There are a hundred other tasks awaiting my attention, {class}. Do you have the books?", completion = "Good, {class}. You have done well in serving the Dark Lady. Your continued perseverance and ambition will be of great use to the Lady's subjects. Return to me again in the future. Perhaps I will have other tasks for you that will aid the Dark Lady in her attempts at overtaking the Lich King and completely freeing the Scourge." } })
apply(5726, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Insignie schon, {name}?\n\nSie wäre ein wichtiges Hilfsmittel, damit Ihr dort eindringen könnt, wo ich die größte Gefahr für die Horde vermute und damit wir in unserer neuen Heimat endlich Frieden finden.\n\nIhr werdet sehen, wie komplex das Netz sein kann, das Menschen und Orcs gemeinsam weben können, wenn sie von Gier und Machthunger angetrieben werden. All die geheimen Pläne, die Verderbnis, all das wird dann klar werden. Ihr werdet Euch in der Mitte eines Krieges wiederfinden, von dem Ihr gar nicht wusstet, dass er überhaupt existiert.", completion = "Gut, {name}! Die Geister seien gepriesen. Vielleicht seid Ihr derjenige, der mich endlich von meinen größten Sorgen befreien kann! Wer hätte gedacht, dass jemand, der so jung und doch so mutig ist, sich erheben und unsere Sache verfechten würde? Ihr erinnert mich an mich selbst, als ich noch jünger war. Ich werde dafür sorgen, dass Ihr den gerechten Lohn für Eure Mühen bekommt, falls wir den aufziehenden Sturm überleben.\n\nWeitere Lobeshymnen heben wir uns für später auf. Bis jetzt habt Ihr nicht viel geleistet im Vergleich zu dem, was Euch noch erwartet... aber es ist ein guter Anfang." }, enUS = { progress = "Do you have the insignia yet, {name}?\n\nIt will be a vital tool in infiltrating what I believe is the greatest threat to the Horde, and finally finding peace in our new home.\n\nYou will learn how intricate a web men and orcs alike can weave when they are motivated by greed and power. The hidden agendas, the corruption, all of it will become clear. You will find yourself in the midst of a war you never knew existed.", completion = "Good, {name}! The spirits be praised, perhaps you are the one who will finally put my greatest fears to rest! Who would suspect someone so young and so brave would rise up and champion our cause? You remind me of myself when I was younger. I will ensure that you are justly rewarded for your efforts if we both survive the coming storm.\n\nBut there is time for more praise later. You've not accomplished anything in comparison to what you will face... but this is a good start." } })
apply(5727, { "classic", "forever" }, { deDE = { progress = "Also, {class}? Hat er uns unsere Finte abgenommen oder ist die Sache doch schlimmer, als ich zuerst angenommen habe?\n\nWenn wir uns für Neeru als nützlich erweisen, wird uns das die Unterwanderung des Schattenrates erleichtern. Wir werden an eine Menge Informationen herankommen, die wir nutzen können, um all jene auszurotten, die das zu zerstören versuchen, was wir in Durotar aufgebaut haben.", completion = "Exzellent! Sehr eindrucksvoll, {class}!\n\nWas Euch heute gelungen ist, ist nur der erste Schritt zur Legung eines noch größeren Fundaments - eines Fundaments, auf dem wir die endgültige Zerstörung des Schattenrates aufbauen.\n\nErzählt mir alles, was er gesagt hat... und lasst auch nicht ein einziges Wort aus, denn es könnte wichtiger sein, als Ihr glaubt." }, enUS = { progress = "Well, {class}? Does he believe our ploy, or are things worse than I had first estimated?\n\nProving valuable to Neeru will make our infiltration of the Shadow Council much easier. He will have plenty of information that we can use to route out those who would destroy all we have built in Durotar.", completion = "Excellent! Most excellent, {class}!\n\nWhat you have done this day is only the first step in a much broader foundation--a foundation that we will build the destruction of the Shadow Council on, once and for all.\n\nTell me all he said... and leave not one word out--it may be more important than you realize." } })
apply(5729, { "classic", "forever" }, { deDE = { completion = "Was ist? Oh, Ihr seid es, {class}... Verzeiht mir. Ich bin so wütend wie ein tollwütiger Kodobulle... aber daran bin ich wahrscheinlich selbst schuld. Ich habe Reisende zum Ragefireabgrund geschickt und hätte doch wissen müssen, dass sich daraus Probleme ergeben könnten. Es scheint, als hätten ein paar von Thralls Weltverbesserern Bazzalan und Jergosh überrumpelt und erschlagen. Ein äußerst ungünstiger Zeitpunkt, aber daran ist jetzt nichts mehr zu ändern." }, enUS = { completion = "What is it?! Oh, you, {class}... my apologies. My anger rivals that of a rabid kodo bull... but perhaps it is my own fault. In sending travelers into Ragefire Chasm, I should have seen the possibility that some harm would come from it. It seems both Bazzalan and Jergosh were taken unaware and slain by some of Thrall's do-gooders. A most inopportune time, but there is nothing that can be done about it now." } })
apply(5730, { "classic", "forever" }, { deDE = { completion = "Ashenvale? Hmm, ich hatte nichts von der Anwesenheit des Rates oder der Burning Blade in Ashenvale gewusst. Meine Spione werden das untersuchen, {name}. Das habt Ihr gut gemacht.\n\nJetzt ruht Euch erst einmal aus und beschäftigt Euch mit anderen Aufgaben. Ich werde Euch bald wieder benötigen.\n\nLok-Tar Ogar!" }, enUS = { completion = "Ashenvale? Hmm, I had not heard of any presence of the Council or the Burning Blade in Ashenvale. My spies will investigate, {name}. You have done well.\n\nFor now, rest, and keep yourself occupied with other tasks. I will call upon you again soon.\n\nLok-Tar Ogar!" } })
apply(5741, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Szepter des Lichts?", completion = "Das geheimnisvolle Szepter des Lichts! Dass Ihr es beschafft habt, hat eine große Bedrohung von der Welt abgewendet. Gut gemacht, {class}, gut gemacht." }, enUS = { progress = "Do you have the Sceptre of Light?", completion = "The elusive Sceptre of Light!  Your acquisition of it has removed a grave threat to the world.  Well done, {class}, well done." } })
apply(5742, { "classic", "forever" }, { deDE = { progress = "Bitte setzt Euch und hört meine Geschichte.", completion = "Fordring zu erlösen wird sehr schwierig sein. Seid Ihr bereit?" }, enUS = { progress = "Please, friend; sit and hear my tale.", completion = "The Fordring redemption will be a difficult task. Are you prepared?" } })
apply(5761, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Bestie getötet? Er ist mit Sicherheit der Anführer der Searingblade im Ragefireabgrund.", completion = "Ha! Ihr habt es geschafft! Thrall wird hocherfreut sein.\n\nIch werde dafür sorgen, dass das Herz in die richtigen Hände kommt.\n\nJetzt allerdings solltet Ihr erst einmal Euren Sieg feiern. Ich werde indes Thrall von Eurem Erfolg berichten.\n\nVielen Dank für Eure Hilfe, {class}." }, enUS = { progress = "Have you killed the beast? He surely must be the leader of the Searing Blade in Ragefire Chasm.", completion = "Ha! You've done it! Thrall will be so pleased.\n\nI will ensure this heart is taken care of properly.\n\nFor now though, you must celebrate your victory. I will inform Thrall of your success.\n\nThank you for your aid, {class}." } })
apply(5762, { "classic", "forever" }, { deDE = { progress = "Ist das da Wüstenstaub an Eurem Kragen?\n\nHm... wenn mich meine Nase nicht täuscht, würde ich sagen, das ist gar kein Wüstenstaub, sondern Wüstensalz! Ihr wart in der schimmernden Ebene, stimmt's?", completion = "Großartig, meine Sendung von Koalbeard! Danke, {name}. Diese Kiste enthält Munition eines ganz besonderen Kalibers, die uns im Dschungel sehr nützen wird!\n\nHier habt Ihr das Geld und sagt mir noch, wie geht's denn dem grantigen alten Kravel so? Führt bestimmt immer noch nichts Gutes im Schilde, möchte ich wetten ..." }, enUS = { progress = "Is that desert dust on your collar?\n\nHm... if my nose tells true, I'd say it's not desert dust, it's desert salt!   Been to the Shimmering Flats, have you?", completion = "Great, my package from Koalbeard!  Thank you {name}.  This crate holds special-gauge ammunition, and it'll serve us well out in the jungle!\n\nHere's your pay, and tell me, how is crusty old Kravel these days?  Still up to no good I'd wager..." } })
apply(5763, { "classic", "forever" }, { deDE = { progress = "Setzt Euch, {class}. Ihr werdet schon bald wieder in den Dschungel zurückmüssen.", completion = "Ah, dieses Horn gehört einem Tauren, Roon Wildmane. Wir hatten sehr viel Spaß, als wir zusammen die Wildtiere von Desolace jagten. Roon lädt mich also ein, ja?\n\nWir stecken zwar momentan bis zum Hals im Dschungel, aber trotzdem danke, {name}. Vielleicht führt mich meine nächste Expedition ja wieder nach Desolace, dem Land der Zentauren." }, enUS = { progress = "Sit, {class}.  Soon enough you'll strike back into the jungle.", completion = "Ah, this horn belongs to a Tauren, Roon Wildmane.  He and I had a good time hunting the beasts of Desolace.  So Roon is inviting me back, is he?\n\nWe're neck deep in the jungle right now, but thank you, {name}.  Perhaps my next expedition will take me back to Desolace, the land of the centaurs." } })
apply(5781, { "classic", "forever" }, { deDE = { progress = "Er muss erlöst werden.", completion = "<Tirion blinzelt, um seine Tränen zurückzuhalten.>\n\nEs war Schicksal, dass wir uns begegneten, {name}. Ihr wart so gut zu mir." }, enUS = { progress = "He must be redeemed.", completion = "<Tirion blinks to hold back tears.>\n\nIt was destiny that we meet, {name}. You have blessed me with your kindness." } })
apply(5801, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, {name}? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem ruchlosen Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel." }, enUS = { progress = "Do you have the stem of the skeletal key finished?  I'm sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we {name}?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the nefarious being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own." } })
apply(5802, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir wirklich Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, {name}? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel." }, enUS = { progress = "Do you have the stem of the skeletal key finished?  I'm truly sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we {name}?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own." } })
apply(5805, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5821, { "classic", "forever" }, { deDE = { completion = "Wisst Ihr, es scheint mir nicht besonders lukrativ zu sein, jemanden wie Euch dafür zu bezahlen, Gizeltons Karawane zu beschützen. {class}, wenn ich ein bisschen größer wäre, könnte ich einen Nebenjob annehmen und mit der größten Schusswaffe in der Hand auf Kodos reiten. Und dann würde ich den vermaledeiten Zentauren echt mal zeigen, wer hier der Boss ist." }, enUS = { completion = "You know, it doesn't seem prosperous to be paying the likes of you to guard Gizelton Caravan. {class}, if I were a bit taller I could take on a second job and sit kodo-side-saddle with the biggest gun my hands could carry... and I'd show them blasted centaur who's their papa." } })
apply(5841, { "classic", "forever" }, { deDE = { progress = "Hallo! {name} ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5842, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5843, { "classic", "forever" }, { deDE = { progress = "Hallo! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5844, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5845, { "classic", "forever" }, { deDE = { progress = "Mein Glaube wird Euch leiten, {name}. Das Licht kennt keine Grenzen.", completion = "Sie ist noch genauso prachtvoll - sogar in diesem zerlumpten Zustand - wie an dem Tag, als ich sie sah und meinen Treueid darauf schwor.\n\nSeine Erlösung naht, und mit ihr vielleicht auch meine..." }, enUS = { progress = "My faith will guide you, {name}. The Light knows no bounds.", completion = "It is as glorious now - even in its tattered state - as the day I looked upon it and took my oath of allegiance.\n\nHis redemption comes and perhaps mine with it..." } })
apply(5846, { "classic", "forever" }, { deDE = { completion = "Wie konnte ich das nur vergessen? Viele der Geister auf dieser Insel sind dazu verdammt, ihre letzte glückliche Erinnerung vor ihrem tragischen Ende noch einmal zu durchleben.\n\nIch bin ebenfalls verdammt, aber auf andere Weise als sie - ich bin einer der wenigen, die sich an alles erinnern ...\n\nVielleicht ist das, worum Ihr mich batet, der Grund, warum ich in diesen Ruinen spuke. Vielleicht es das, was mich befreien kann." }, enUS = { completion = "How could I forget? Many of the spirits on this island are cursed to relive their last happy memory before they met their tragic end.\n\nI too am cursed, but not as they - I am one of the few that remembers all...\n\nPerhaps this thing that you ask me is why I haunt these ruins. Perhaps this thing I tell you shall set me free." } })
apply(5847, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!" }, enUS = { progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" } })
apply(5848, { "classic", "forever" }, { deDE = { progress = "Das Gemälde, {name}. Habt Ihr das Gemälde?", completion = "<Tirion bricht beinahe zusammen, als er das Gemälde sieht.>\n\n<Er beginnt hemmungslos zu weinen.>" }, enUS = { progress = "The painting, {name}. Do you have the painting?", completion = "<Tirion nearly collapses when he sees the painting.>\n\n<He begins to sob in an almost frenetic manner.>" } })
apply(5863, { "classic", "forever" }, { deDE = { completion = "Ich bin ja so froh, dass Ihr das für mich tun konntet, {name}! Ich danke Euch für Eure Hilfe!" }, enUS = { completion = "I'm so glad you were able to do this for me, {name}! Thanks for your help!" } })
apply(5881, { "classic", "forever" }, { deDE = { progress = "Ihr habt Nachricht von Maggran Earthbinder?", completion = "Dies sind großartige Neuigkeiten. Ich sitze schon viel zu lang hier herum und bewache diesen Holzblock. Jetzt kann ich endlich etwas Zeit mit meiner Familie verbringen... Jippie!" }, enUS = { progress = "You have news from Maggran Earthbinder?", completion = "This is great news; I have been sitting here guarding this hunk of wood for too long. Now I can spend some time with my family... Yippee!" } })
apply(5901, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Termiten schon, {name}? Ich bin sicher, dass es für jemanden, der so schlau ist wie Ihr, {class}, ganz einfach ist.\n\nSobald wir genug davon haben, sorgen wir dafür, dass niemand dieses Sägewerk je wieder verwenden kann!", completion = "Die sind prima, {name}. Danke.\n\nWenn Ihr bereit seid, können wir uns dem nächsten Schritt zuwenden." }, enUS = { progress = "Do you have the termites yet, {name}? I am sure it is obvious to a smart {class} like yourself.\n\nOnce we have enough of them, we'll make sure no one can use the lumber mill ever again!", completion = "These will do nicely, {name}. Thank you.\n\nIf you're ready, we can get on with the next step." } })
apply(5903, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Termitenhügel gefunden, {name}? Ich habe gehört, es gibt sie überall im Pestwald.", completion = "Die sind prima, {name}. Danke. Schaut sie Euch nur an... so viele von ihnen, alle auf einem Haufen. Ich habe schon beinahe Mitleid mit dem Kreuzzug, aber es war ja schließlich niemals ihre Mühle, nicht wahr?" }, enUS = { progress = "Did you find the termite mounds, {name}? I've heard they are all over Plaguewood.", completion = "These will do nicely, {name}. Thank you. Just look at them... so many of them all huddled up. I almost feel bad for the Crusade, but then again, it was never their mill to take, now, was it?" } })
apply(5923, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!" }, enUS = { completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" } })
apply(5924, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!" }, enUS = { completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" } })
apply(5925, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!" }, enUS = { completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" } })
apply(5926, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!" }, enUS = { completion = "I am glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" } })
apply(5928, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!" }, enUS = { completion = "I am glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" } })
apply(5929, { "classic", "forever" }, { deDE = { progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"" }, enUS = { progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"" } })
apply(5930, { "classic", "forever" }, { deDE = { progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"" }, enUS = { progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"" } })
apply(5931, { "classic", "forever" }, { deDE = { completion = "Willkommen, {name}. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir verlassen uns heute auf seine Weisheit und seine Macht, um unseren Absichten Antrieb zu verleihen. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu..." }, enUS = { completion = "Welcome back, {name}.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We have come to rely on its wisdom and its power to fuel our purpose.  The time has now come for your first test of this purpose.  Listen closely..." } })
apply(5932, { "classic", "forever" }, { deDE = { completion = "Willkommen, {name}. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir {race} hören solchen Geistern genau zu und wir alle profitieren von deren Absichten. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu..." }, enUS = { completion = "Welcome back, {name}.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We {race} listen closely to such spirits, and we all prosper from its purpose.  Now, the time has now come for your first test of this purpose.  Listen closely..." } })
apply(5941, { "classic", "forever" }, { deDE = { progress = "Ich stand in Kontakt mit Eurem Freund Carlin. Er leidet sehr unter dem Untergang seines Dorfes, doch er spricht sehr gut von Euch und weiß, dass Ihr die Dinge richten könnt.\n\nOh, ich fürchte ich schweife vom Thema ab... {name}, habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ach ja, da sind sie ja. Gemeinsam weben sie einen mächtigen Zauber, einen, der die Geister von Darrowshire wiedererwecken wird.\n\nMit diesem Zauber und etwas Glück können wir Joseph Redpath retten!" }, enUS = { progress = "I have been in contact with your friend Carlin.  He feels great pain for the doom of his village, but he speaks very highly of you and knows that you can set things right.\n\nOh, but I'm drifting from the subject at hand... {name}, do you have the relics I asked for?", completion = "Ah yes, there they are.  Together they weave a powerful spell, one that will raise the spirits of Darrowshire.\n\nWith that spell, and with a little luck, we can save Joseph Redpath!" } })
apply(5943, { "classic", "forever" }, { deDE = { completion = "Ich bin mir nicht sicher, ob es zu ihrem Erfolg beiträgt, Euch so viel Geld für den Schutz von Gizeltons Karawane zu bezahlen. Cork und Rigger verdienen gerade mal ein Goldstück pro Woche, doch solange sie schön meine Kodos bezahlen, kann es mir eigentlich egal sein, wie sie ihre Geschäfte machen." }, enUS = { completion = "Not sure it's a prosperous proposition to be paying so much money to protect the Gizelton Caravan. Cork and Rigger only make one gold piece a week, but as long as they keep paying for my kodos I can care less how they run their business." } })
apply(5961, { "classic", "forever" }, { deDE = { completion = "Gewiss hält Euch die Dunkle Fürstin nicht für würdig, ihren Champion zu treffen. Seid Ihr hier, um meine Hunde zu füttern, ja? Einen anderen Grund für diese Unterbrechung kann es nicht geben." }, enUS = { completion = "Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption." } })
apply(6001, { "classic", "forever" }, { deDE = { completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, {name}. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein {class} der Klaue zu sein." }, enUS = { completion = "You have finally taken your large step into a much larger world, {name}.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a {class} of the Claw!" } })
apply(6002, { "classic", "forever" }, { deDE = { completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, {name}. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein {class} der Klaue zu sein." }, enUS = { completion = "You have finally taken your large step into a much larger world, {name}.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a {class} of the Claw!" } })
apply(6004, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Ich bin erstaunt, dass Ihr so schnell mit ihnen fertig geworden seid. Danke.\n\nIch habe noch niemanden getroffen, der den Scharlachroten Kreuzzug und dessen Methoden gutgeheißen hätte. Ich glaube so sehr wie jeder andere in Stormwind an das Licht, sie aber haben bewiesen, dass sie nur alle töten wollen, die nicht treu zu ihrer Bewegung stehen ... selbst Unschuldige." }, enUS = { completion = "Well done, {name}. I'm amazed you dealt with them so quickly. Thank you.\n\nI have yet to meet anyone that approves of the Scarlet Crusade and their methods. I believe in the Light as much as anyone else in Stormwind, but they've demonstrated that they only want to kill anyone not loyal to their movement... even innocents." } })
apply(6021, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Versteck gefunden, {name}? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!" }, enUS = { progress = "Did you find the hideout, {name}?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!" } })
apply(6022, { "classic", "forever" }, { deDE = { progress = "Weint Ihr etwa? Wenn Euch das zu 'anstrengend' ist, oh 'Held', dann rate ich Euch, kehrt zur Dunklen Fürstin zurück und erzählt ihr von der schrecklichen Behandlung, die Euch auf meinem Bauernhof zuteil wurde.\n\nUnd jetzt geht mir aus den Augen!", completion = "Enttäuschend. Ich hatte gehofft, ich würde stattdessen Euch an meine Hunde verfüttern können.\n\n<Nathanos seufzt.>\n\nNa, wenigstens haben sie etwas zu fressen." }, enUS = { progress = "Are you crying? If this is too 'tedious' for you, 'hero,' I recommend that you head back to the Dark Lady and inform her of the horrible mistreatment you received at my farmstead.\n\nNow get out of my sight!", completion = "Disappointing. I was hoping that I'd be feeding you to my hounds, instead.\n\n<Nathanos sighs.>\n\nWell, at least they'll have something to eat." } })
apply(6023, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Ihr habt mir mehr geholfen als ich hoffen durfte. Die Luft hier scheint mir die Willenskraft auszusaugen. Ich bin müde und spüre, dass es sich nicht bessern wird, solange ich hier bin.\n\nIch habe wirklich keine Ahnung, wie ich nach Hearthglen hineingelangen und melden soll, wie stark die Präsenz des Scharlachroten Kreuzzugs dort ist.\n\nAber das ist ein anderes Thema. Bevor Ihr geht, hier, nehmt dies... als Bezahlung für Eure Hilfe. Nochmals danke." }, enUS = { completion = "Thank you, {name}. You've been more help than I could have hoped for. The air here just seems to suck my will. I feel tired, and I can tell I'm not getting any better the longer I'm here.\n\nI'm not really sure how I'm going to infiltrate Hearthglen itself and report on how strong the Scarlet Crusade's presence is.\n\nBut that's another matter, before you leave, here, take this... as payment for your help. Thank you again." } })
apply(6024, { "classic", "forever" }, { deDE = { progress = "Die hier vergrabene Truhe ist fest verschlossen.", completion = "Hameyas Truhe wurde geöffnet!!!" }, enUS = { progress = "This chest buried here is securely locked.", completion = "Hameya's chest is opened!!" } })
apply(6025, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft, {name}! Danke!\n\nIch kehre zu Elling zurück... Ich meine nach Stormwind, so schnell ich kann. Hier, nehmt diese Münze, das ist das Mindeste, was ich für Euch tun kann. Ihr macht Eurem Volk Ehre, {name}. Habt Dank, und viel Glück." }, enUS = { completion = "You've done it, {name}! Thank you!\n\nI'll return to Elling... I mean Stormwind as soon as I can. Here, take this coin, it's the least I can do for you. You're a credit to your people, {name}. Thank you and good luck." } })
apply(6026, { "classic", "forever" }, { deDE = { progress = "Vertraut dem alten Smokey, {race}. Es wird sich lohnen. Die Leute von der Argentumdämmerung machen kein Gewese, was Bezahlung angeht.", completion = "Ich bezahle Euch eine Hälfte gleich und die andere, wenn die Aufgabe erledigt ist." }, enUS = { progress = "Trust ol' Smokey, {race}. The reward will be worth it. These Argent Dawn folk don't mess around when it comes to payment.", completion = "I can pay you half up front and half when the job is done." } })
apply(6027, { "classic", "forever" }, { deDE = { progress = "Ah, {name}! Schön, Euch zu wiederzusehen. Habt Ihr das 'Buch der Uralten'?", completion = "Das lange verschollene 'Buch der Uralten'! Ich werde dafür sorgen, dass der Hohe Rat dieses Buch bekommt. Ihr habt heute Großes vollbracht, und dafür muss man Euch danken... wie man einem Helden dankt!" }, enUS = { progress = "Ah, {name}!  It's good to see you again.  Do you have the Book of the Ancients?", completion = "The long lost Book of the Ancients!  I will ensure this book is passed on to the high council.  You've done well today, and for that you are to be thanked... as a hero should be thanked!" } })
apply(6028, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Chillwind-Lager seid. Vielleicht habe ich auch ein bisschen Arbeit für Euch...", completion = "Gregor ist außerordentlich findig. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank." }, enUS = { progress = "Greetings, {class}.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp.  I might also have some work for you...", completion = "Very resourceful, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks." } })
